const $=(s,e=document)=>e.querySelector(s);const $$=(s,e=document)=>[...e.querySelectorAll(s)];
const defaultState={empresa:{nome:'Metalúrgica e Serralheria Universal',razaoSocial:'Serralheria Universal R. do Vale Pedrosa & Cia LTDA',cnpj:'09.360.662/0001-47',telefone:'(65) 3684-4041',whatsapp:'556536844696',endereco:'Av. Sen. Filinto Müller, 3223 - Jardim Paula II, Várzea Grande - MT, 78135-181',logoUrl:'/universal-logo.png',validade:15,freteVG:0,freteCuiaba:100,medidaPortao:'3,10 x 2,10 m',medidaPorta:'0,80 x 2,10 m',ga4Id:'',metaPixelId:''},clientes:[],vendedores:[],produtores:[],produtos:[],estoqueMateriais:[],movimentosEstoque:[],orcamentos:[],pedidos:[],auditoria:[]};
let state=structuredClone(defaultState),stateVersion='',currentUser=null,currentView='dashboard',pendingAudit=null,saveQueue=Promise.resolve(),usersCache=[],installPrompt=null;

const titles={dashboard:['Visão geral','Acompanhe orçamentos, pedidos, produção e entregas.'],orcamentos:['Orçamentos','Monte propostas com medidas, descontos e frete.'],pedidos:['Pedidos / OS','Pedidos aprovados, ordens de serviço e histórico.'],producao:['Produção','Fila, responsáveis, carga e prioridades.'],entregas:['Entregas','Produtos prontos, agendamentos e atrasos.'],clientes:['Clientes','Cadastre clientes e registre a origem comercial.'],produtos:['Produtos','Catálogo público e referências para orçamento.'],estoque:['Estoque de materiais','Cadastre materiais, entradas e acompanhe o consumo da produção.'],vendedores:['Vendedores','Equipe responsável pelos atendimentos.'],produtores:['Produtores','Equipe de fabricação e carga atribuída.'],relatorios:['Relatórios','Indicadores comerciais, produção, entrega e marketing.'],usuarios:['Usuários','Acessos individuais, perfis e permissões.'],auditoria:['Auditoria','Histórico protegido das alterações críticas.'],config:['Configurações','Dados da empresa, frete e rastreamento.']};
const VIEW_ROLES={dashboard:['administrador','gerente','vendedor','conferencia','entrega'],orcamentos:['administrador','gerente','vendedor'],pedidos:['administrador','gerente','vendedor','conferencia','entrega'],producao:['administrador','gerente','vendedor','conferencia'],entregas:['administrador','gerente','vendedor','conferencia','entrega'],clientes:['administrador','gerente','vendedor'],produtos:['administrador','gerente','vendedor'],estoque:['administrador','gerente','conferencia'],vendedores:['administrador','gerente'],produtores:['administrador','gerente'],relatorios:['administrador','gerente'],usuarios:['administrador'],auditoria:['administrador','gerente'],config:['administrador','gerente']};

function roleLabel(r){return({administrador:'Administrador',gerente:'Gerente',vendedor:'Vendedor',conferencia:'Conferência',entrega:'Entrega'})[r]||r}
function canView(v){return VIEW_ROLES[v]?.includes(currentUser?.role)}
function hasPerm(k){return currentUser?.role==='administrador'||Boolean(currentUser?.permissions?.[k])}
function brl(v){return new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(Number(v)||0)}
function dt(v){if(!v)return '—';const s=String(v).slice(0,10),[y,m,d]=s.split('-');return y&&m&&d?`${d}/${m}/${y}`:v}
function todayISO(){return new Date().toLocaleDateString('en-CA',{timeZone:'America/Cuiaba'})}
function uid(p='id'){return `${p}_${Date.now().toString(36)}_${Math.random().toString(36).slice(2,8)}`}
function esc(v=''){return String(v).replace(/[&<>'"]/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[m]))}
function toast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2800)}
function modal(html){$('#modalContent').innerHTML=html;if(!$('#modal').open)$('#modal').showModal()}
function closeModal(){if($('#modal').open)$('#modal').close();$('#modalContent').innerHTML=''}
function audit(action,detail,collection='',entityId=''){pendingAudit={action,detail,collection,entityId}}
function statusBudget(s){return({rascunho:['Rascunho',''],enviado:['Enviado','info'],aprovado:['Aprovado','ok'],recusado:['Recusado','danger'],vencido:['Vencido','warn']})[s]||[s,'']}
function statusOrder(s){return({pendente:['Pendente','warn'],producao:['Em produção','info'],pronto:['Pronto','ok'],entregue:['Entregue','ok'],cancelado:['Cancelado','danger']})[s]||[s,'']}
function nextNumber(prefix,arr,key='numero'){const year=new Date().getFullYear();const max=arr.reduce((m,x)=>Math.max(m,Number((x[key]||'').split('-').pop())||0),0);return `${prefix}-${year}-${String(max+1).padStart(4,'0')}`}
function clientName(id){return state.clientes.find(x=>x.id===id)?.nome||'Cliente não localizado'}
function sellerName(id){return state.vendedores.find(x=>x.id===id)?.nome||'—'}
function producerName(id){return state.produtores.find(x=>x.id===id)?.nome||'Não atribuído'}
function productName(id,fallback){const found=state.produtos.find(x=>x.id===id)?.nome;if(found)return found;return arguments.length>1?String(fallback||''):'Item personalizado'}
function materialName(id){return state.estoqueMateriais.find(x=>x.id===id)?.nome||'Material não localizado'}
function materialUnit(id){return state.estoqueMateriais.find(x=>x.id===id)?.unidade||''}
function fieldInput(label,id,type,value='',attrs=''){return `<div class="field"><label>${label}</label><input id="${id}" type="${type}" value="${esc(value)}" ${attrs}></div>`}
function fieldSelect(label,id,value,opts,placeholder='',attrs=''){return `<div class="field"><label>${label}</label><select id="${id}" ${attrs}>${placeholder?`<option value="">${esc(placeholder)}</option>`:''}${opts.map(([v,l])=>`<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(l)}</option>`).join('')}</select></div>`}

async function api(path,options={}){const r=await fetch('/api/'+path,{credentials:'same-origin',...options,headers:{...(options.body instanceof FormData?{}:{'content-type':'application/json'}),...(options.headers||{})}});let data={};try{data=await r.json()}catch{}if(!r.ok){const e=new Error(data.error||'Erro na operação.');e.status=r.status;e.code=data.code;throw e}return data}

function showAuth(type){$('#authScreen').classList.remove('hidden');$('#appShell').classList.add('hidden');$('#bootstrapBox').classList.toggle('hidden',type!=='bootstrap');$('#loginBox').classList.toggle('hidden',type!=='login');$('#authError').style.display='none'}
function authError(msg){$('#authError').textContent=msg;$('#authError').style.display='block'}
async function initAuth(){try{const st=await api('bootstrap/status');if(st.needsBootstrap){showAuth('bootstrap');return}try{const me=await api('me');currentUser=me.user;if(currentUser.mustChangePassword){showAuth('login');$('#authScreen').classList.add('hidden');forcePasswordChange();return}await enterApp()}catch{showAuth('login')}}catch(e){showAuth('login');authError('Não foi possível conectar ao banco de dados. Confira o binding D1 chamado DB no Cloudflare.')}}
$('#bootstrapBtn').onclick=async()=>{try{await api('bootstrap',{method:'POST',body:JSON.stringify({name:$('#bootName').value,email:$('#bootEmail').value,password:$('#bootPassword').value})});showAuth('login');$('#loginEmail').value=$('#bootEmail').value;toast('Administrador criado. Faça o login.')}catch(e){authError(e.message)}};
$('#loginBtn').onclick=login;$('#loginPassword').addEventListener('keydown',e=>{if(e.key==='Enter')login()});
async function login(){try{const r=await api('login',{method:'POST',body:JSON.stringify({email:$('#loginEmail').value,password:$('#loginPassword').value})});currentUser=r.user;if(currentUser.mustChangePassword){$('#authScreen').classList.add('hidden');forcePasswordChange();return}await enterApp()}catch(e){authError(e.message)}}
async function forcePasswordChange(){modal(`<div class="modal-head"><strong>Troca obrigatória de senha</strong></div><div class="modal-body"><div class="notice warn">Este usuário está com senha temporária. Defina uma nova senha antes de acessar o sistema.</div><div style="height:14px"></div>${fieldInput('Nova senha','newPassword','password','','minlength="8" autocomplete="new-password"')}</div><div class="modal-foot"><button class="btn primary" onclick="changePasswordNow()">Salvar nova senha</button></div>`)}
window.changePasswordNow=async()=>{try{await api('change-password',{method:'POST',body:JSON.stringify({password:$('#newPassword').value})});currentUser.mustChangePassword=false;closeModal();await enterApp();toast('Senha alterada.')}catch(e){toast(e.message)}};
async function enterApp(){const r=await api('state');state={...structuredClone(defaultState),...r.state,empresa:{...defaultState.empresa,...(r.state.empresa||{})}};stateVersion=r.version||'';currentUser=r.user||currentUser;$('#authScreen').classList.add('hidden');$('#appShell').classList.remove('hidden');applyRoleUI();renderAll();if(!canView(currentView))switchView('dashboard')}
$('#logoutBtn').onclick=async()=>{try{await api('logout',{method:'POST'})}catch{}location.reload()};

function applyRoleUI(){const initials=(currentUser.name||'U').split(' ').slice(0,2).map(x=>x[0]).join('').toUpperCase();$('#userChip').innerHTML=`<div class="avatar">${esc(initials)}</div><div><strong>${esc(currentUser.name)}</strong><span>${roleLabel(currentUser.role)}</span></div>`;$('#sideUser').textContent=`${currentUser.name} · ${roleLabel(currentUser.role)}`;$$('.nav-btn').forEach(b=>b.classList.toggle('hidden',!canView(b.dataset.view)));$$('.admin-only').forEach(x=>x.classList.toggle('hidden',currentUser.role!=='administrador'));$$('.admin-manager').forEach(x=>x.classList.toggle('hidden',!['administrador','gerente'].includes(currentUser.role)));$$('.can-budget').forEach(x=>x.classList.toggle('hidden',!['administrador','gerente','vendedor'].includes(currentUser.role)))}
function switchView(v){if(!canView(v))return toast('Seu perfil não tem acesso a esta área.');currentView=v;$$('.view').forEach(x=>x.classList.remove('active'));$(`#view-${v}`).classList.add('active');$$('.nav-btn').forEach(x=>x.classList.toggle('active',x.dataset.view===v));$('#pageTitle').textContent=titles[v][0];$('#pageSubtitle').textContent=titles[v][1];renderAll();if(v==='usuarios')loadUsers();if(v==='relatorios')loadMarketing()}
$$('.nav-btn').forEach(b=>b.addEventListener('click',()=>switchView(b.dataset.view)));

function save(){renderAll();const meta=pendingAudit||{action:'Alteração no sistema',detail:'Atualização de dados'};pendingAudit=null;const snapshot=structuredClone(state);saveQueue=saveQueue.then(async()=>{try{const r=await api('state',{method:'PUT',body:JSON.stringify({state:snapshot,audit:meta,version:stateVersion})});state={...structuredClone(defaultState),...r.state,empresa:{...defaultState.empresa,...(r.state.empresa||{})}};stateVersion=r.version||stateVersion;renderAll()}catch(e){toast(e.message);try{const fresh=await api('state');state={...structuredClone(defaultState),...fresh.state,empresa:{...defaultState.empresa,...(fresh.state.empresa||{})}};stateVersion=fresh.version||'';renderAll()}catch{}}});return saveQueue}

function renderAll(){renderDashboard();renderBudgets();renderOrders();renderProduction();renderDeliveries();renderClients();renderProducts();renderStock();renderSellers();renderProducers();renderReports();renderAudit();renderConfig()}

function renderDashboard(){const today=todayISO(),active=state.pedidos.filter(p=>!['entregue','cancelado'].includes(p.status)),late=active.filter(p=>(p.prazoEntrega||p.prazo)&& (p.prazoEntrega||p.prazo)<today),due=active.filter(p=>(p.prazoEntrega||p.prazo)===today),pending=state.orcamentos.filter(o=>['rascunho','enviado'].includes(o.status)),approved=state.orcamentos.filter(o=>o.status==='aprovado'&&(o.data||'').slice(0,7)===today.slice(0,7)),approvedValue=approved.reduce((s,o)=>s+calcBudget(o).final,0);$('#view-dashboard').innerHTML=`<div class="grid cards">${metric('Orçamentos em aberto',pending.length,'rascunhos e enviados')}${metric('Pedidos ativos',active.length,'em andamento')}${metric('Entregas hoje',due.length,due.length?'exigem atenção':'nenhuma pendência')}${metric('Atrasados',late.length,late.length?'prazo vencido':'tudo em dia',late.length?'danger-text':'ok-text')}</div><div style="height:16px"></div><div class="banner"><div><strong>Valor aprovado no mês: ${brl(approvedValue)}</strong><p>Somatório dos orçamentos aprovados no mês atual.</p></div>${['administrador','gerente','vendedor'].includes(currentUser?.role)?'<button class="btn gold" onclick="openBudget()">Criar orçamento</button>':''}</div><div style="height:16px"></div><div class="grid kpi-split"><div class="card"><div class="row between"><h3 class="section-title">Pedidos que precisam de atenção</h3><button class="btn small" onclick="switchView('pedidos')">Ver todos</button></div><div style="height:12px"></div>${attentionList(late,due)}</div><div class="card"><div class="row between"><h3 class="section-title">Últimos orçamentos</h3></div><div style="height:12px"></div>${lastBudgets()}</div></div>`}
function metric(label,value,hint,cls=''){return `<div class="card metric"><div class="label">${label}</div><div class="value ${cls}">${value}</div><div class="hint">${hint}</div></div>`}
function attentionList(late,due){const arr=[...late.map(x=>({...x,_flag:'Atrasado'})),...due.map(x=>({...x,_flag:'Entrega hoje'}))].slice(0,8);if(!arr.length)return `<div class="empty"><strong>Nenhum pedido crítico</strong>Não há entregas vencidas ou para hoje.</div>`;return `<div class="list">${arr.map(p=>`<div class="list-item"><div><strong>${esc(p.numero)}</strong><div class="muted">${esc(clientName(p.clienteId))} · ${dt(p.prazoEntrega||p.prazo)}</div></div><span class="pill ${p._flag==='Atrasado'?'danger':'warn'}">${p._flag}</span></div>`).join('')}</div>`}
function lastBudgets(){const arr=state.orcamentos.slice().sort((a,b)=>(b.createdAt||'').localeCompare(a.createdAt||'')).slice(0,5);if(!arr.length)return `<div class="empty"><strong>Nenhum orçamento ainda</strong>Crie o primeiro orçamento.</div>`;return `<div class="list">${arr.map(o=>{const [lab,cls]=statusBudget(o.status);return `<div class="list-item"><div><strong>${esc(o.numero)}</strong><div class="muted">${esc(clientName(o.clienteId))} · ${brl(calcBudget(o).final)}</div></div><span class="pill ${cls}">${lab}</span></div>`}).join('')}</div>`}

function renderBudgets(){if(!canView('orcamentos'))return;const rows=state.orcamentos.slice().sort((a,b)=>(b.createdAt||'').localeCompare(a.createdAt||''));$('#view-orcamentos').innerHTML=`<div class="table-card"><div class="table-tools"><div class="toolbar"><input class="search" id="budgetSearch" placeholder="Buscar orçamento ou cliente..."><select id="budgetStatus" class="search"><option value="">Todos os status</option><option value="rascunho">Rascunho</option><option value="enviado">Enviado</option><option value="aprovado">Aprovado</option><option value="recusado">Recusado</option></select></div><button class="btn primary" onclick="openBudget()">+ Novo orçamento</button></div><div id="budgetTable">${budgetTable(rows)}</div></div>`;$('#budgetSearch').oninput=filterBudgets;$('#budgetStatus').onchange=filterBudgets}
function budgetTable(rows){if(!rows.length)return `<div class="empty"><strong>Nenhum orçamento cadastrado</strong>Crie o primeiro orçamento.</div>`;return `<div class="table-wrap"><table><thead><tr><th>Número</th><th>Data</th><th>Cliente</th><th>Vendedor</th><th>Valor final</th><th>Status</th><th>Ações</th></tr></thead><tbody>${rows.map(o=>{const [lab,cls]=statusBudget(o.status);return `<tr><td><strong>${esc(o.numero)}</strong></td><td>${dt(o.data)}</td><td>${esc(clientName(o.clienteId))}</td><td>${esc(sellerName(o.vendedorId))}</td><td><strong>${brl(calcBudget(o).final)}</strong></td><td><span class="pill ${cls}">${lab}</span></td><td><div class="actions"><button class="btn small" onclick="openBudget('${o.id}')">Abrir</button><button class="btn small" onclick="printBudget('${o.id}')">PDF / Imprimir</button>${o.status==='aprovado'&&!state.pedidos.some(p=>p.orcamentoId===o.id)?`<button class="btn small success" onclick="createOrderFromBudget('${o.id}')">Gerar pedido + OS</button>`:''}</div></td></tr>`}).join('')}</tbody></table></div>`}
function filterBudgets(){const q=($('#budgetSearch')?.value||'').toLowerCase(),st=$('#budgetStatus')?.value||'';$('#budgetTable').innerHTML=budgetTable(state.orcamentos.filter(o=>(!st||o.status===st)&&(`${o.numero} ${clientName(o.clienteId)}`.toLowerCase().includes(q))))}
function blankItem(){return{id:uid('item'),produtoId:'',produtoNome:'',medidas:'',quantidade:1,descricao:'',valorOriginal:0,descontoTipo:'valor',desconto:0,carga:1}}
function normalizeClientText(v=''){return String(v).normalize('NFD').replace(/[\u0300-\u036f]/g,'').trim().toLowerCase().replace(/\s+/g,' ')}
function normalizeClientDigits(v=''){return String(v).replace(/\D/g,'')}
function budgetClientFromForm(){return{nome:$('#bClienteNome')?.value.trim()||'',telefone:$('#bClienteTelefone')?.value.trim()||'',email:$('#bClienteEmail')?.value.trim()||'',documento:$('#bClienteDocumento')?.value.trim()||'',cidade:$('#bClienteCidade')?.value.trim()||'',endereco:$('#bClienteEndereco')?.value.trim()||''}}
function findMatchingBudgetClient(data,selectedId=''){if(selectedId){const selected=state.clientes.find(c=>c.id===selectedId);if(selected)return selected}const documentDigits=normalizeClientDigits(data.documento);if(documentDigits){const byDocument=state.clientes.find(c=>normalizeClientDigits(c.documento)===documentDigits);if(byDocument)return byDocument}const phoneDigits=normalizeClientDigits(data.telefone);if(phoneDigits){const byPhone=state.clientes.find(c=>normalizeClientDigits(c.telefone)===phoneDigits);if(byPhone)return byPhone}const name=normalizeClientText(data.nome),address=normalizeClientText(data.endereco);if(name&&address)return state.clientes.find(c=>normalizeClientText(c.nome)===name&&normalizeClientText(c.endereco)===address)||null;return null}
function upsertBudgetClient(data,selectedId=''){const existing=findMatchingBudgetClient(data,selectedId);if(existing){Object.assign(existing,{...data,id:existing.id,origem:existing.origem||'Orçamento',updatedAt:new Date().toISOString()});return{id:existing.id,created:false}}const client={id:uid('cli'),...data,origem:'Orçamento',campanha:'',anuncio:'',obs:'Cadastro criado automaticamente ao salvar orçamento.',createdAt:new Date().toISOString()};state.clientes.push(client);return{id:client.id,created:true}}
window.fillBudgetClient=function(id){const c=state.clientes.find(x=>x.id===id);const values=c||{nome:'',telefone:'',email:'',documento:'',cidade:'',endereco:''};[['bClienteNome','nome'],['bClienteTelefone','telefone'],['bClienteEmail','email'],['bClienteDocumento','documento'],['bClienteCidade','cidade'],['bClienteEndereco','endereco']].forEach(([field,key])=>{const el=$('#'+field);if(el)el.value=values[key]||''});const hint=$('#budgetClientHint');if(hint)hint.textContent=c?'Cadastro existente carregado. Alterações serão atualizadas ao salvar.':'Preencha os dados abaixo. O cadastro será criado automaticamente.'}
window.openBudget=function(id){const existing=state.orcamentos.find(x=>x.id===id);const o=existing?structuredClone(existing):{id:uid('orc'),numero:nextNumber('ORC',state.orcamentos),versao:1,data:todayISO(),validadeDias:Number(state.empresa.validade)||15,clienteId:'',vendedorId:'',cidade:'Várzea Grande',frete:0,status:'rascunho',obs:'',formaPagamento:'',prazoEntrega:'',descontoGeralTipo:'valor',descontoGeral:0,itens:[blankItem()],createdAt:new Date().toISOString()};const client=state.clientes.find(x=>x.id===o.clienteId)||{},discountDisabled=hasPerm('discount')?'':'disabled',clientOptions=state.clientes.slice().sort((a,b)=>a.nome.localeCompare(b.nome)).map(x=>[x.id,`${x.nome}${x.telefone?' · '+x.telefone:''}`]);modal(`<div class="modal-head"><div><strong>${existing?'Editar':'Novo'} orçamento</strong><div class="muted">${o.numero} · versão ${o.versao||1}</div></div><button class="icon-btn" onclick="closeModal()">×</button></div><div class="modal-body"><form id="budgetForm"><div class="row between"><div><strong>Dados do cliente</strong><div class="muted" id="budgetClientHint">${o.clienteId?'Cadastro existente carregado. Alterações serão atualizadas ao salvar.':'Digite os dados agora; ao salvar, o cliente será cadastrado automaticamente.'}</div></div></div><div style="height:12px"></div><div class="form-grid three">${fieldSelect('Cliente já cadastrado (opcional)','bCliente',o.clienteId,clientOptions,'Novo cliente / preencher abaixo')}${fieldInput('Nome / Razão social','bClienteNome','text',client.nome||'','required')}${fieldInput('Telefone / WhatsApp','bClienteTelefone','text',client.telefone||'')}${fieldInput('E-mail','bClienteEmail','email',client.email||'')}${fieldInput('CPF / CNPJ','bClienteDocumento','text',client.documento||'')}${fieldInput('Cidade do cliente','bClienteCidade','text',client.cidade||o.cidade||'Várzea Grande')}<div class="field full"><label>Endereço</label><input id="bClienteEndereco" value="${esc(client.endereco||'')}"></div></div><div class="divider"></div><div class="form-grid three">${fieldSelect('Vendedor responsável','bVendedor',o.vendedorId,state.vendedores.filter(x=>x.ativo!==false).map(x=>[x.id,x.nome]),'Selecione um vendedor')}${fieldInput('Data','bData','date',o.data)}${fieldSelect('Cidade / frete','bCidade',o.cidade,[['Várzea Grande','Várzea Grande — frete grátis'],['Cuiabá','Cuiabá — R$ 100,00'],['Outra','Outra cidade — informar frete']])}${fieldInput('Validade (dias)','bValidade','number',o.validadeDias,'min="1"')}${fieldSelect('Status','bStatus',o.status,[['rascunho','Rascunho'],['enviado','Enviado'],['aprovado','Aprovado'],['recusado','Recusado']])}</div><div class="divider"></div><div class="row between"><div><strong>Itens do orçamento</strong><div class="muted">Produto/serviço pode ser cadastrado ou digitado manualmente. Medidas, descrição e observações são opcionais.</div></div></div><div id="budgetItems"></div><div class="row" style="justify-content:flex-end;margin-top:10px"><button type="button" class="btn small" onclick="addBudgetItem()">+ Adicionar item</button></div><div class="divider"></div><div class="form-grid three">${fieldSelect('Desconto geral','bDiscType',o.descontoGeralTipo,[['valor','Valor (R$)'],['percentual','Percentual (%)']],'',discountDisabled)}${fieldInput('Desconto','bDisc','number',o.descontoGeral,`min="0" step="0.01" ${discountDisabled}`)}<div class="field"><label>Frete aplicado</label><input id="bFrete" type="number" min="0" step="0.01" value="${Number(o.frete)||0}"><small class="muted" id="freteHint"></small></div>${fieldInput('Forma de pagamento','bPagamento','text',o.formaPagamento||'')}${fieldInput('Prazo informado ao cliente','bPrazo','text',o.prazoEntrega||'')}<div class="field full"><label>Condições e observações</label><textarea id="bObs">${esc(o.obs||'')}</textarea></div></div>${!hasPerm('discount')?'<div class="notice warn">Seu usuário não possui permissão para conceder ou alterar descontos.</div>':''}<div class="divider"></div><div id="budgetSummary"></div></form></div><div class="modal-foot"><button class="btn" onclick="closeModal()">Cancelar</button><button class="btn primary" onclick="saveBudget()">Salvar orçamento</button></div>`);window._budgetDraft=o;$('#bCliente').onchange=e=>fillBudgetClient(e.target.value);renderBudgetItems();bindBudgetCalc();updateFrete(true);calcBudgetDraft()}
function renderBudgetItems(){const d=window._budgetDraft,discountDisabled=hasPerm('discount')?'':'disabled';$('#budgetItems').innerHTML=d.itens.map((it,i)=>`<div class="item-row budget-item-flex" data-i="${i}">${fieldSelect('Produto cadastrado','i_prod_'+i,it.produtoId,state.produtos.filter(p=>!p.arquivado||p.id===it.produtoId).map(p=>[p.id,p.nome]),'Não cadastrado / personalizado')}<div class="field"><label>Produto / serviço</label><input id="i_name_${i}" value="${esc(it.produtoNome||productName(it.produtoId,''))}" placeholder="Ex.: Portão sob medida, reforma, solda..."></div>${fieldInput('Medidas','i_med_'+i,'text',it.medidas||'','placeholder="Opcional"')}${fieldInput('Qtd.','i_qtd_'+i,'number',it.quantidade,'min="1" step="1"')}<div class="field budget-desc"><label>Descrição manual <span class="optional">(opcional)</span></label><input id="i_desc_${i}" value="${esc(it.descricao||'')}" placeholder="Material, cor, abertura, acabamento..."></div>${fieldInput('Valor original','i_val_'+i,'number',it.valorOriginal,'min="0" step="0.01"')}<div class="field"><label>Desc. item</label><div class="row"><select id="i_dt_${i}" ${discountDisabled}><option value="valor" ${it.descontoTipo==='valor'?'selected':''}>R$</option><option value="percentual" ${it.descontoTipo==='percentual'?'selected':''}>%</option></select><input id="i_dv_${i}" type="number" min="0" step="0.01" value="${Number(it.desconto)||0}" ${discountDisabled}></div></div><div class="field"><label>&nbsp;</label><button type="button" class="btn danger" onclick="removeBudgetItem(${i})">×</button></div></div>`).join('')}
window.addBudgetItem=function(){syncDraftFromForm();window._budgetDraft.itens.push(blankItem());renderBudgetItems();bindBudgetCalc();calcBudgetDraft()};window.removeBudgetItem=function(i){syncDraftFromForm();if(window._budgetDraft.itens.length===1)return toast('O orçamento precisa ter pelo menos um item.');window._budgetDraft.itens.splice(i,1);renderBudgetItems();bindBudgetCalc();calcBudgetDraft()};
function bindBudgetCalc(){['bCidade','bDiscType','bDisc','bFrete'].forEach(id=>{const el=$('#'+id);if(el)el.oninput=()=>{if(id==='bCidade')updateFrete(true);calcBudgetDraft()}});window._budgetDraft.itens.forEach((_,i)=>['prod','name','med','qtd','desc','val','dt','dv'].forEach(k=>{const el=$(`#i_${k}_${i}`);if(el)el.oninput=()=>{if(k==='prod'){const p=state.produtos.find(x=>x.id===el.value);if(p){$(`#i_name_${i}`).value=p.nome||'';$(`#i_med_${i}`).value=p.medidaPadrao||'';$(`#i_val_${i}`).value=Number(p.preco)||0;window._budgetDraft.itens[i].carga=Number(p.carga)||1}else if(!$(`#i_name_${i}`).value.trim()){$(`#i_med_${i}`).value=''}}calcBudgetDraft()}}))}
function updateFrete(force=false){const city=$('#bCidade')?.value,frete=$('#bFrete'),hint=$('#freteHint');if(!frete)return;if(city==='Várzea Grande'){if(force)frete.value=Number(state.empresa.freteVG)||0;hint.textContent='Frete grátis em Várzea Grande.'}else if(city==='Cuiabá'){if(force)frete.value=Number(state.empresa.freteCuiaba)||100;hint.textContent='Taxa padrão de R$ 100,00 para Cuiabá.'}else hint.textContent='Informe o valor manualmente.'}
function syncDraftFromForm(){const d=window._budgetDraft;if(!d)return;d.clienteId=$('#bCliente')?.value||'';d.vendedorId=$('#bVendedor')?.value||'';d.data=$('#bData')?.value||d.data;d.validadeDias=Number($('#bValidade')?.value)||15;d.cidade=$('#bCidade')?.value||d.cidade;d.status=$('#bStatus')?.value||d.status;if(hasPerm('discount')){d.descontoGeralTipo=$('#bDiscType')?.value||d.descontoGeralTipo;d.descontoGeral=Number($('#bDisc')?.value)||0}d.frete=Number($('#bFrete')?.value)||0;d.formaPagamento=$('#bPagamento')?.value||'';d.prazoEntrega=$('#bPrazo')?.value||'';d.obs=$('#bObs')?.value||'';d.itens=d.itens.map((it,i)=>({...it,produtoId:$(`#i_prod_${i}`)?.value||'',produtoNome:$(`#i_name_${i}`)?.value.trim()||productName($(`#i_prod_${i}`)?.value||'',''),medidas:$(`#i_med_${i}`)?.value||'',quantidade:Math.max(1,Number($(`#i_qtd_${i}`)?.value)||1),descricao:$(`#i_desc_${i}`)?.value||'',valorOriginal:Number($(`#i_val_${i}`)?.value)||0,descontoTipo:hasPerm('discount')?($(`#i_dt_${i}`)?.value||'valor'):it.descontoTipo,desconto:hasPerm('discount')?(Number($(`#i_dv_${i}`)?.value)||0):it.desconto}))}
function calcBudget(o){let original=0,itemDiscount=0;for(const it of(o.itens||[])){const base=(Number(it.valorOriginal)||0)*(Number(it.quantidade)||0);original+=base;itemDiscount+=it.descontoTipo==='percentual'?base*(Math.min(100,Math.max(0,Number(it.desconto)||0))/100):Math.min(base,Math.max(0,Number(it.desconto)||0)*(Number(it.quantidade)||1))}const afterItems=Math.max(0,original-itemDiscount),general=o.descontoGeralTipo==='percentual'?afterItems*(Math.min(100,Math.max(0,Number(o.descontoGeral)||0))/100):Math.min(afterItems,Math.max(0,Number(o.descontoGeral)||0)),freight=Math.max(0,Number(o.frete)||0);return{original,itemDiscount,afterItems,general,freight,final:Math.max(0,afterItems-general+freight)}}
function calcBudgetDraft(){syncDraftFromForm();const c=calcBudget(window._budgetDraft);$('#budgetSummary').innerHTML=`<div class="summary"><div class="summary-line"><span>Valor original</span><strong>${brl(c.original)}</strong></div>${c.itemDiscount?`<div class="summary-line"><span>Descontos nos itens</span><span>- ${brl(c.itemDiscount)}</span></div>`:''}${c.general?`<div class="summary-line"><span>Desconto geral</span><span>- ${brl(c.general)}</span></div>`:''}<div class="summary-line"><span>Frete</span><span>+ ${brl(c.freight)}</span></div><div class="summary-line total"><span>Total</span><span>${brl(c.final)}</span></div></div>`}
window.saveBudget=function(){syncDraftFromForm();const d=window._budgetDraft,clientData=budgetClientFromForm();if(!clientData.nome)return toast('Informe o nome do cliente.');if(!d.vendedorId)return toast('Selecione o vendedor responsável.');if(!d.itens.length)return toast('Inclua pelo menos um item.');if(d.itens.some(i=>!String(i.produtoNome||productName(i.produtoId,'')).trim()))return toast('Informe o produto ou serviço de cada item.');const clientResult=upsertBudgetClient(clientData,$('#bCliente')?.value||d.clienteId||'');d.clienteId=clientResult.id;const idx=state.orcamentos.findIndex(x=>x.id===d.id),old=idx>=0?state.orcamentos[idx]:null;if(old?.status==='aprovado'){d.versao=(Number(old.versao)||1)+1}d.updatedAt=new Date().toISOString();const detail=`${d.numero} · ${clientName(d.clienteId)}${clientResult.created?' · cliente cadastrado automaticamente':''}`;if(idx>=0){state.orcamentos[idx]=d;audit('Orçamento alterado',detail,'orcamentos',d.id)}else{state.orcamentos.push(d);audit('Orçamento criado',detail,'orcamentos',d.id)}save();closeModal();toast(clientResult.created?'Orçamento salvo e cliente cadastrado automaticamente.':'Orçamento salvo. Cadastro do cliente atualizado.')}
window.printBudget=function(id){const o=state.orcamentos.find(x=>x.id===id);if(!o)return;const c=calcBudget(o),cli=state.clientes.find(x=>x.id===o.clienteId)||{},hasItem=(o.itens||[]).some(i=>Number(i.desconto)>0),hasGeneral=Number(o.descontoGeral)>0,validUntil=(()=>{const d=new Date((o.data||todayISO())+'T12:00:00');d.setDate(d.getDate()+(Number(o.validadeDias)||15));return d.toLocaleDateString('pt-BR')})();const logoUrl=state.empresa.logoUrl||'/universal-logo.png',logo=logoUrl?`<img class="quote-logo-img" src="${esc(logoUrl)}" alt="Universal">`:`<div class="quote-logo"><span class="quote-bars"><i></i><i></i><i></i></span><span><small>SERRALHERIA E METALÚRGICA</small><strong>UNIVERSAL</strong><em>TRABALHO DE QUALIDADE!</em></span></div>`;modal(`<div class="printable"><div class="print-controls modal-head"><strong>Pré-visualização do orçamento</strong><div><button class="btn" onclick="closeModal()">Fechar</button> <button class="btn primary" onclick="printCurrentDocument()">Gerar PDF / Imprimir</button></div></div><div class="print-doc quote-doc"><header class="quote-head"><div class="quote-brand">${logo}</div><div class="quote-company"><strong>${esc(state.empresa.razaoSocial||state.empresa.nome)}</strong><span>CNPJ: ${esc(state.empresa.cnpj||'')}</span><span>Telefone: ${esc(state.empresa.telefone||'')}</span><span>WhatsApp: ${esc(formatWhatsApp(state.empresa.whatsapp)||'')}</span><span>${esc(state.empresa.endereco||'')}</span></div><div class="quote-id"><b>ORÇAMENTO</b><strong>${esc(o.numero)}</strong><span>Versão ${o.versao||1}</span><span>Emissão: ${dt(o.data)}</span><span>Validade: ${validUntil}</span></div></header><section class="quote-client"><div><span>Cliente</span><strong>${esc(cli.nome||clientName(o.clienteId))}</strong></div><div><span>CPF/CNPJ</span><strong>${esc(cli.documento||'—')}</strong></div><div><span>Telefone</span><strong>${esc(cli.telefone||'—')}</strong></div><div><span>E-mail</span><strong>${esc(cli.email||'—')}</strong></div><div class="wide"><span>Endereço</span><strong>${esc(cli.endereco||'—')}</strong></div><div><span>Cidade</span><strong>${esc(cli.cidade||o.cidade||'—')}</strong></div><div><span>Responsável</span><strong>${esc(sellerName(o.vendedorId))}</strong></div></section><table class="quote-table"><thead><tr><th>Produto / serviço</th><th>Medidas</th><th>Qtd.</th><th>Descrição</th><th class="money">Valor original</th>${hasItem?'<th class="money">Desconto</th>':''}<th class="money">Valor final</th></tr></thead><tbody>${o.itens.map(it=>{const base=(Number(it.valorOriginal)||0)*(Number(it.quantidade)||0),disc=it.descontoTipo==='percentual'?base*(Number(it.desconto)||0)/100:(Number(it.desconto)||0)*(Number(it.quantidade)||1);return `<tr><td><strong>${esc(it.produtoNome||productName(it.produtoId,''))}</strong></td><td>${esc(it.medidas||'—')}</td><td>${it.quantidade}</td><td>${esc(it.descricao||'—')}</td><td class="money">${brl(base)}</td>${hasItem?`<td class="money">${disc?'- '+brl(disc):'—'}</td>`:''}<td class="money"><strong>${brl(Math.max(0,base-disc))}</strong></td></tr>`}).join('')}</tbody></table><section class="quote-bottom"><div class="quote-notes"><h4>Condições e observações gerais</h4><div>${o.obs?esc(o.obs).replace(/\n/g,'<br>'):'Sem observações.'}</div>${o.formaPagamento?`<p><strong>Forma de pagamento:</strong> ${esc(o.formaPagamento)}</p>`:''}${o.prazoEntrega?`<p><strong>Prazo de entrega:</strong> ${esc(o.prazoEntrega)}</p>`:''}<p><strong>Validade da proposta:</strong> ${Number(o.validadeDias)||15} dias.</p></div><div class="totals quote-totals"><div><span>Valor original</span><span>${brl(c.original)}</span></div>${c.itemDiscount?`<div><span>Descontos nos itens</span><span>- ${brl(c.itemDiscount)}</span></div>`:''}${hasGeneral?`<div><span>Desconto geral</span><span>- ${brl(c.general)}</span></div>`:''}<div><span>Frete / outros</span><span>${brl(c.freight)}</span></div><div class="grand"><span>TOTAL</span><span>${brl(c.final)}</span></div></div></section><footer class="quote-sign"><span>________________________________________<br>Cliente / Contratante</span><span>________________________________________<br>Metalúrgica e Serralheria Universal</span></footer></div></div>`)}
window.printCurrentDocument=async function(){const images=$$('.printable img');await Promise.all(images.map(img=>img.complete?Promise.resolve():new Promise(resolve=>{let settled=false;const finish=()=>{if(settled)return;settled=true;resolve()};img.addEventListener('load',finish,{once:true});img.addEventListener('error',finish,{once:true});setTimeout(finish,2000)})));window.print()}
function formatWhatsApp(v=''){const d=String(v).replace(/\D/g,'');const n=d.startsWith('55')?d.slice(2):d;return n.length===11?`(${n.slice(0,2)}) ${n.slice(2,7)}-${n.slice(7)}`:n.length===10?`(${n.slice(0,2)}) ${n.slice(2,6)}-${n.slice(6)}`:v}


window.createOrderFromBudget=function(id){const o=state.orcamentos.find(x=>x.id===id);if(!o||o.status!=='aprovado')return;if(state.pedidos.some(p=>p.orcamentoId===id))return toast('Já existe um pedido para este orçamento.');const carga=(o.itens||[]).reduce((s,it)=>{const pr=state.produtos.find(x=>x.id===it.produtoId);return s+(Number(pr?.carga||it.carga||1)*Number(it.quantidade||1))},0);const p={id:uid('ped'),numero:nextNumber('PED',state.pedidos),osNumero:nextNumber('OS',state.pedidos,'osNumero'),orcamentoId:o.id,orcamentoVersao:o.versao||1,clienteId:o.clienteId,vendedorId:o.vendedorId,data:todayISO(),prazoProducao:'',prazoEntrega:'',status:'pendente',etapa:'aguardando',produtorId:'',carga:carga||1,obs:o.obs||'',valor:calcBudget(o).final,itens:structuredClone(o.itens||[]),materiaisConsumidos:[],materiaisBaixados:false,materiaisBaixadosEm:'',attachments:[],historicoResponsavel:[],entrega:{agendadaEm:'',entregueEm:'',recebedor:'',observacao:'',pagamentoStatus:'pendente',pagamentoForma:'',pagamentoCondicao:'avista',parcelas:1,valorReceber:calcBudget(o).final},createdAt:new Date().toISOString()};state.pedidos.push(p);audit('Pedido e OS gerados',`${p.numero} / ${p.osNumero} a partir de ${o.numero}`,'pedidos',p.id);save();toast('Pedido e OS gerados. Defina produção e entrega.');openOrder(p.id)}
function renderOrders(){if(!canView('pedidos'))return;const today=todayISO(),rows=state.pedidos.slice().sort((a,b)=>(a.prazoEntrega||'9999').localeCompare(b.prazoEntrega||'9999'));$('#view-pedidos').innerHTML=`<div class="table-card"><div class="table-tools"><div class="toolbar"><input class="search" id="orderSearch" placeholder="Buscar pedido, OS ou cliente..."><select id="orderFilter" class="search"><option value="">Todos</option><option value="atrasados">Atrasados</option><option value="hoje">Entrega hoje</option><option value="ativos">Ativos</option><option value="pronto">Prontos</option><option value="entregues">Entregues</option></select></div><span class="muted">Orçamento aprovado → pedido → OS → produção → entrega.</span></div><div id="orderTable">${orderTable(rows,today)}</div></div>`;$('#orderSearch').oninput=filterOrders;$('#orderFilter').onchange=filterOrders}
function orderTable(rows,today=todayISO()){if(!rows.length)return `<div class="empty"><strong>Nenhum pedido ainda</strong>Aprove um orçamento e use “Gerar pedido + OS”.</div>`;return `<div class="table-wrap"><table><thead><tr><th>Pedido / OS</th><th>Cliente</th><th>Produtor</th><th>Carga</th><th>Entrega</th><th>Prazo</th><th>Status</th><th>Ações</th></tr></thead><tbody>${rows.map(p=>{const [lab,cls]=statusOrder(p.status),deadline=deadlineLabel(p);return `<tr><td><strong>${esc(p.numero)}</strong><div class="muted">${esc(p.osNumero||'')}</div></td><td>${esc(clientName(p.clienteId))}</td><td>${esc(producerName(p.produtorId))}</td><td>${Number(p.carga)||0}</td><td>${dt(p.prazoEntrega)}</td><td><span class="pill ${deadline.cls}">${deadline.label}</span></td><td><span class="pill ${cls}">${lab}</span></td><td><div class="actions"><button class="btn small" onclick="openOrder('${p.id}')">Abrir</button><button class="btn small" onclick="printOS('${p.id}')">Imprimir OS</button></div></td></tr>`}).join('')}</tbody></table></div>`}
function deadlineLabel(p){const today=todayISO(),date=p.prazoEntrega||p.prazoProducao;if(!date)return{label:'Sem prazo',cls:'warn'};if(['entregue','cancelado'].includes(p.status))return{label:'Finalizado',cls:''};if(date<today)return{label:'Atrasado',cls:'danger'};if(date===today)return{label:'Hoje',cls:'warn'};return{label:'No prazo',cls:'ok'}}
function filterOrders(){const q=($('#orderSearch')?.value||'').toLowerCase(),f=$('#orderFilter')?.value||'',today=todayISO();let rows=state.pedidos.filter(p=>(`${p.numero} ${p.osNumero||''} ${clientName(p.clienteId)}`.toLowerCase().includes(q)));if(f==='atrasados')rows=rows.filter(p=>!['entregue','cancelado'].includes(p.status)&&p.prazoEntrega&&p.prazoEntrega<today);if(f==='hoje')rows=rows.filter(p=>!['entregue','cancelado'].includes(p.status)&&p.prazoEntrega===today);if(f==='ativos')rows=rows.filter(p=>!['entregue','cancelado'].includes(p.status));if(f==='pronto')rows=rows.filter(p=>p.status==='pronto');if(f==='entregues')rows=rows.filter(p=>p.status==='entregue');$('#orderTable').innerHTML=orderTable(rows,today)}
function blankConsumedMaterial(){return{id:uid('mc'),materialId:'',quantidade:0,observacao:''}}
function consumedMaterialRows(p){const locked=Boolean(p.materiaisBaixados);const rows=(p.materiaisConsumidos||[]);return `<div id="consumedMaterials">${rows.map((m,i)=>`<div class="material-consume-row">${fieldSelect('Material','mc_mat_'+i,m.materialId,state.estoqueMateriais.filter(x=>x.ativo!==false||x.id===m.materialId).map(x=>[x.id,`${x.nome} · saldo ${Number(x.quantidade||0).toLocaleString('pt-BR')} ${x.unidade||''}`]),'Selecione',locked?'disabled':'')}${fieldInput('Quantidade consumida','mc_qtd_'+i,'number',m.quantidade,`min="0" step="0.01" ${locked?'disabled':''}`)}<div class="field"><label>Unidade</label><input value="${esc(materialUnit(m.materialId)||'—')}" disabled></div><div class="field"><label>Observação <span class="optional">(opcional)</span></label><input id="mc_obs_${i}" value="${esc(m.observacao||'')}" ${locked?'disabled':''}></div><div class="field"><label>&nbsp;</label>${locked?'':`<button class="btn danger" type="button" onclick="removeConsumedMaterial(${i})">×</button>`}</div></div>`).join('')||'<div class="empty compact">Nenhum material informado.</div>'}</div>`}
window.addConsumedMaterial=function(){const p=window._orderDraft;if(!p)return;p.materiaisConsumidos=p.materiaisConsumidos||[];syncConsumedMaterials(p);p.materiaisConsumidos.push(blankConsumedMaterial());renderConsumedMaterials(p)}
