function syncConsumedMaterials(p){if(!p)return;p.materiaisConsumidos=(p.materiaisConsumidos||[]).map((m,i)=>({...m,materialId:$(`#mc_mat_${i}`)?.value||m.materialId||'',quantidade:Number($(`#mc_qtd_${i}`)?.value)||0,observacao:$(`#mc_obs_${i}`)?.value||''})).filter(m=>m.materialId||m.quantidade)}
function renderConsumedMaterials(p){const box=$('#materialsConsumptionBox');if(box)box.innerHTML=consumedMaterialRows(p)}
function applyStockConsumption(p){if(p.materiaisBaixados)return;const valid=(p.materiaisConsumidos||[]).filter(x=>x.materialId&&Number(x.quantidade)>0);for(const c of valid){const m=state.estoqueMateriais.find(x=>x.id===c.materialId);if(!m)continue;const q=Number(c.quantidade)||0;m.quantidade=(Number(m.quantidade)||0)-q;state.movimentosEstoque.unshift({id:uid('mov'),materialId:m.id,tipo:'saida_producao',quantidade:q,efeito:-q,data:todayISO(),pedidoId:p.id,osNumero:p.osNumero||'',responsavel:currentUser?.name||'',observacao:c.observacao||`Consumo da ${p.osNumero||p.numero}`,createdAt:new Date().toISOString()})}p.materiaisBaixados=true;p.materiaisBaixadosEm=new Date().toISOString()}

window.openOrder=function(id){const p=state.pedidos.find(x=>x.id===id);if(!p)return;const canTransfer=hasPerm('transferProduction'),custom=(p.itens||[]).some(i=>!i.produtoId);p.materiaisConsumidos=p.materiaisConsumidos||[];window._orderDraft=p;modal(`<div class="modal-head"><div><strong>${esc(p.numero)} · ${esc(p.osNumero||'')}</strong><div class="muted">${esc(clientName(p.clienteId))}</div></div><button class="icon-btn" onclick="closeModal()">×</button></div><div class="modal-body"><div class="form-grid three">${fieldInput('Data do pedido','pData','date',p.data||todayISO())}${fieldInput('Prazo de produção','pProdPrazo','date',p.prazoProducao||'')}${fieldInput('Prazo de entrega','pEntPrazo','date',p.prazoEntrega||'')}${fieldSelect('Status','pStatus',p.status,[['pendente','Pendente'],['producao','Em produção'],['pronto','Pronto'],['entregue','Entregue'],['cancelado','Cancelado']])}${fieldSelect('Etapa','pEtapa',p.etapa||'aguardando',[['aguardando','Aguardando produção'],['em_fabricacao','Em fabricação'],['aguardando_conferencia','Aguardando conferência'],['liberado','Liberado para entrega'],['concluido','Concluído']])}${fieldSelect('Produtor responsável','pProdutor',p.produtorId||'',state.produtores.filter(x=>x.ativo!==false||x.id===p.produtorId).map(x=>[x.id,x.nome]),'Não atribuído',p.produtorId&&!canTransfer?'disabled':'')}${fieldInput('Carga estimada','pCarga','number',p.carga||1,'min="0" step="0.5"')}<div class="field"><label>Valor</label><input value="${brl(p.valor)}" disabled></div><div class="field"><label>Orçamento vinculado</label><input value="${esc(state.orcamentos.find(o=>o.id===p.orcamentoId)?.numero||'—')} · v${p.orcamentoVersao||1}" disabled></div><div class="field full"><label>Observações da OS <span class="optional">(opcional)</span></label><textarea id="pObs">${esc(p.obs||'')}</textarea></div>${p.produtorId&&canTransfer?`<div class="field full"><label>Motivo da transferência (obrigatório se trocar o produtor)</label><input id="pTransferMotivo" placeholder="Explique por que a OS foi transferida"></div>`:''}</div><div class="divider"></div><div class="row between"><div><strong>Materiais consumidos na produção</strong><div class="muted">O serralheiro informa o consumo real. Ao mudar a etapa para <b>Concluído</b>, o sistema baixa o estoque automaticamente.</div></div>${p.materiaisBaixados?'<span class="pill ok">Estoque já baixado</span>':'<button type="button" class="btn small" onclick="addConsumedMaterial()">+ Material consumido</button>'}</div><div id="materialsConsumptionBox" style="margin-top:10px">${consumedMaterialRows(p)}</div>${p.materiaisBaixados?`<div class="notice" style="margin-top:10px">Baixa realizada em ${new Date(p.materiaisBaixadosEm).toLocaleString('pt-BR',{timeZone:'America/Cuiaba'})}. Para correção posterior, faça um ajuste manual no estoque para preservar o histórico.</div>`:''}<div class="divider"></div><div class="row between"><div><strong>Anexos e referências</strong><div class="muted">Fotos, croquis e PDFs ficam no R2 privado.</div></div><label class="btn small">+ Anexar arquivo<input id="orderFile" type="file" accept="image/*,application/pdf" hidden onchange="uploadOrderAttachment('${p.id}',this)"></label></div><div style="height:10px"></div><div class="gallery">${(p.attachments||[]).map(a=>`<div class="gallery-item"><a class="btn small" href="${esc(a.url)}" target="_blank">${esc(a.name||'Arquivo')}</a></div>`).join('')||'<span class="muted">Nenhum anexo.</span>'}</div>${custom?'<div style="height:12px"></div><div class="notice warn"><strong>Pedido personalizado:</strong> confira produto/serviço, medidas e instruções necessárias antes de iniciar a fabricação. Anexos são recomendados quando houver croqui, foto ou projeto.</div>':''}<div class="divider"></div><div class="form-grid three">${fieldInput('Entrega agendada','pAgendada','date',p.entrega?.agendadaEm||'')}${fieldInput('Data da entrega','pEntregue','date',p.entrega?.entregueEm||'')}${fieldInput('Recebedor','pRecebedor','text',p.entrega?.recebedor||'')}<div class="field full"><label>Observação da entrega <span class="optional">(opcional)</span></label><textarea id="pEntregaObs">${esc(p.entrega?.observacao||'')}</textarea></div></div></div><div class="modal-foot"><button class="btn" onclick="closeModal()">Cancelar</button><button class="btn primary" onclick="saveOrder('${p.id}')">Salvar pedido / OS</button></div>`)}
window.uploadOrderAttachment=async function(id,input){const f=input.files?.[0];if(!f)return;try{const up=await uploadFile(f,'private');const p=state.pedidos.find(x=>x.id===id);p.attachments=p.attachments||[];p.attachments.push(up);audit('Anexo incluído na OS',`${p.osNumero||p.numero} · ${f.name}`,'pedidos',p.id);await save();openOrder(id);toast('Arquivo anexado.')}catch(e){toast(e.message)}}
window.saveOrder=function(id){const p=state.pedidos.find(x=>x.id===id);if(!p)return;syncConsumedMaterials(p);const oldProd=p.produtorId||'',newProd=$('#pProdutor')?.value||oldProd,newStatus=$('#pStatus').value,newStage=$('#pEtapa').value,custom=(p.itens||[]).some(i=>!i.produtoId);if(newStatus==='producao'&&custom){const hasNames=(p.itens||[]).every(i=>String(i.produtoNome||productName(i.produtoId,'')).trim());if(!hasNames)return toast('Informe o produto ou serviço personalizado antes de entrar em produção.')}const completing=newStage==='concluido'&&!p.materiaisBaixados;if(completing){const used=(p.materiaisConsumidos||[]).filter(m=>m.materialId&&Number(m.quantidade)>0);if(!used.length)return toast('Informe ao menos um material consumido antes de concluir a produção.');const missing=used.find(c=>!state.estoqueMateriais.some(m=>m.id===c.materialId));if(missing)return toast('Há material consumido que não existe mais no estoque.')}if(oldProd&&newProd!==oldProd){if(!hasPerm('transferProduction'))return toast('Seu usuário não pode transferir produção.');const motive=$('#pTransferMotivo')?.value.trim();if(!motive)return toast('Informe o motivo da transferência.');p.historicoResponsavel=p.historicoResponsavel||[];p.historicoResponsavel.unshift({from:oldProd,to:newProd,motivo:motive,at:new Date().toISOString(),user:currentUser.name})}p.data=$('#pData').value;p.prazoProducao=$('#pProdPrazo').value;p.prazoEntrega=$('#pEntPrazo').value;p.status=newStatus;p.etapa=newStage;p.produtorId=newProd;p.carga=Number($('#pCarga').value)||0;p.obs=$('#pObs').value;p.entrega={...(p.entrega||{}),agendadaEm:$('#pAgendada').value,entregueEm:$('#pEntregue').value,recebedor:$('#pRecebedor').value,observacao:$('#pEntregaObs').value};if(completing){applyStockConsumption(p);if(p.status==='producao'||p.status==='pendente')p.status='pronto'}if(p.status==='entregue'&&!p.entrega.entregueEm)p.entrega.entregueEm=todayISO();p.updatedAt=new Date().toISOString();audit(completing?'Produção concluída e estoque baixado':oldProd&&newProd!==oldProd?'Responsável de produção transferido':'Pedido / OS atualizado',`${p.numero} · ${statusOrder(p.status)[0]}${completing?' · materiais baixados':''}`,'pedidos',p.id);save();closeModal();toast(completing?'Produção concluída. Materiais baixados do estoque.':'Pedido / OS atualizado.')}

window.printOS=function(id){const p=state.pedidos.find(x=>x.id===id);if(!p)return;modal(`<div class="printable"><div class="print-controls modal-head"><strong>Ordem de Serviço</strong><div><button class="btn" onclick="closeModal()">Fechar</button> <button class="btn primary" onclick="window.print()">Imprimir OS</button></div></div><div class="os-sheet"><div class="brand-print"><div><h1>${esc(state.empresa.nome)}</h1><div>${esc(state.empresa.endereco)}</div><div>${esc(state.empresa.telefone)}</div></div><div><strong>ORDEM DE SERVIÇO</strong><div>${esc(p.osNumero||'')}</div><div>Pedido ${esc(p.numero)}</div></div></div><div class="os-grid"><div class="os-box"><strong>Cliente</strong><br>${esc(clientName(p.clienteId))}</div><div class="os-box"><strong>Vendedor</strong><br>${esc(sellerName(p.vendedorId))}</div><div class="os-box"><strong>Produtor</strong><br>${esc(producerName(p.produtorId))}</div><div class="os-box"><strong>Prazos</strong><br>Produção: ${dt(p.prazoProducao)} · Entrega: ${dt(p.prazoEntrega)}</div></div><h3>Itens aprovados</h3><table><thead><tr><th>Produto</th><th>Medidas</th><th>Qtd.</th><th>Descrição / instruções</th></tr></thead><tbody>${(p.itens||[]).map(i=>`<tr><td>${esc(productName(i.produtoId,i.produtoNome||'Item personalizado'))}</td><td>${esc(i.medidas||'—')}</td><td>${i.quantidade}</td><td>${esc(i.descricao)}</td></tr>`).join('')}</tbody></table><div class="os-grid"><div class="os-box os-manual"><strong>Início da produção</strong><br>Data: ____/____/______ Hora: ________</div><div class="os-box os-manual"><strong>Conclusão</strong><br>Data: ____/____/______ Hora: ________</div><div class="os-box os-manual"><strong>Materiais utilizados</strong><br>${(p.materiaisConsumidos||[]).length?(p.materiaisConsumidos||[]).map(m=>`${esc(materialName(m.materialId))}: ${Number(m.quantidade)||0} ${esc(materialUnit(m.materialId))}`).join('<br>'):'Registrar no painel antes de concluir'}</div><div class="os-box os-manual"><strong>Resultado / observações</strong></div></div><div style="margin-top:30px;display:flex;justify-content:space-between"><span>____________________________<br>Produtor</span><span>____________________________<br>Conferência</span></div></div></div>`)}

function priorityFor(p){const today=new Date(todayISO()+'T12:00:00'),dateStr=p.prazoProducao||p.prazoEntrega;if(!dateStr)return{rank:5,label:'Planejada',cls:'priority-planned',days:null};const d=new Date(dateStr+'T12:00:00'),days=Math.round((d-today)/86400000);if(days<0)return{rank:0,label:`Crítica · ${Math.abs(days)} dia(s) atrasada`,cls:'priority-critical',days};if(days<=1)return{rank:1,label:days===0?'Urgente · vence hoje':'Urgente · vence amanhã',cls:'priority-urgent',days};if(days<=3)return{rank:2,label:`Alta · ${days} dias`,cls:'priority-high',days};if(days<=7)return{rank:3,label:`Normal · ${days} dias`,cls:'priority-normal',days};return{rank:4,label:`Planejada · ${days} dias`,cls:'priority-planned',days}}
function renderProduction(){if(!canView('producao'))return;const rows=state.pedidos.filter(p=>!['pronto','entregue','cancelado'].includes(p.status)).map(p=>({...p,_pr:priorityFor(p)})).sort((a,b)=>a._pr.rank-b._pr.rank||String(a.prazoProducao||'9999').localeCompare(String(b.prazoProducao||'9999')));const loads=state.produtores.filter(x=>x.ativo!==false).map(pr=>{const assigned=rows.filter(p=>p.produtorId===pr.id),load=assigned.reduce((s,p)=>s+Number(p.carga||0),0);return{...pr,load,count:assigned.length}});$('#view-producao').innerHTML=`<div class="grid report-grid">${loads.map(p=>`<div class="card"><div class="row between"><strong>${esc(p.nome)}</strong><span class="pill">${p.count} OS</span></div><div class="metric"><div class="value">${p.load}</div><div class="hint">pontos/horas de carga estimada</div></div><div class="prod-load"><i style="width:${Math.min(100,p.load*10)}%"></i></div></div>`).join('')||'<div class="card">Cadastre produtores para distribuir a produção.</div>'}</div><div style="height:16px"></div><div class="table-card"><div class="table-tools"><div><strong>Relatório diário de produção</strong><div class="muted">Ordenado por atraso e proximidade do prazo.</div></div><button class="btn" onclick="window.print()">Imprimir visão atual</button></div>${rows.length?`<div class="list" style="padding:14px">${rows.map(p=>`<div class="list-item ${p._pr.cls}"><div><strong>${esc(p.osNumero||p.numero)}</strong> · ${esc(clientName(p.clienteId))}<div class="muted">${esc(producerName(p.produtorId))} · carga ${Number(p.carga)||0} · produção ${dt(p.prazoProducao)} · entrega ${dt(p.prazoEntrega)}</div></div><div><span class="pill ${p._pr.rank===0?'danger':p._pr.rank===1?'warn':'info'}">${p._pr.label}</span> <button class="btn small" onclick="openOrder('${p.id}')">Abrir</button></div></div>`).join('')}</div>`:'<div class="empty"><strong>Fila vazia</strong>Nenhuma OS aguardando produção.</div>'}</div>`}

function renderDeliveries(){if(!canView('entregas'))return;const today=todayISO(),rows=state.pedidos.filter(p=>['pronto','entregue'].includes(p.status)||p.entrega?.agendadaEm).sort((a,b)=>(a.entrega?.agendadaEm||a.prazoEntrega||'9999').localeCompare(b.entrega?.agendadaEm||b.prazoEntrega||'9999'));$('#view-entregas').innerHTML=`<div class="grid cards">${metric('Prontos',state.pedidos.filter(p=>p.status==='pronto').length,'aguardando entrega')}${metric('Agendados hoje',rows.filter(p=>p.status!=='entregue'&&p.entrega?.agendadaEm===today).length,'entregas programadas')}${metric('Atrasados',state.pedidos.filter(p=>p.status==='pronto'&&p.prazoEntrega&&p.prazoEntrega<today).length,'prontos com prazo vencido','danger-text')}${metric('Entregues no mês',state.pedidos.filter(p=>p.status==='entregue'&&(p.entrega?.entregueEm||'').slice(0,7)===today.slice(0,7)).length,'concluídos')}</div><div style="height:16px"></div><div class="table-card">${rows.length?`<div class="table-wrap"><table><thead><tr><th>Pedido / OS</th><th>Cliente</th><th>Status</th><th>Prazo</th><th>Agendada</th><th>Entregue</th><th>Ações</th></tr></thead><tbody>${rows.map(p=>`<tr><td><strong>${esc(p.numero)}</strong><div class="muted">${esc(p.osNumero||'')}</div></td><td>${esc(clientName(p.clienteId))}</td><td><span class="pill ${statusOrder(p.status)[1]}">${statusOrder(p.status)[0]}</span></td><td>${dt(p.prazoEntrega)}</td><td>${dt(p.entrega?.agendadaEm)}</td><td>${dt(p.entrega?.entregueEm)}</td><td><button class="btn small" onclick="openOrder('${p.id}')">Atualizar</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty"><strong>Nenhuma entrega para exibir</strong>Pedidos prontos e agendados aparecerão aqui.</div>'}</div>`}

function renderClients(){if(!canView('clientes'))return;const rows=state.clientes.slice().sort((a,b)=>a.nome.localeCompare(b.nome));$('#view-clientes').innerHTML=`<div class="table-card"><div class="table-tools"><input class="search" id="clientSearch" placeholder="Buscar cliente..."><button class="btn primary" onclick="openClient()">+ Novo cliente</button></div><div id="clientTable">${clientTable(rows)}</div></div>`;$('#clientSearch').oninput=()=>{const q=$('#clientSearch').value.toLowerCase();$('#clientTable').innerHTML=clientTable(state.clientes.filter(c=>(`${c.nome} ${c.telefone} ${c.documento}`).toLowerCase().includes(q)))}}
function clientTable(rows){if(!rows.length)return `<div class="empty"><strong>Nenhum cliente cadastrado</strong>Cadastre conforme os atendimentos.</div>`;return `<div class="table-wrap"><table><thead><tr><th>Nome</th><th>Telefone</th><th>CPF/CNPJ</th><th>Cidade</th><th>Origem</th><th>Ações</th></tr></thead><tbody>${rows.map(c=>`<tr><td><strong>${esc(c.nome)}</strong></td><td>${esc(c.telefone||'—')}</td><td>${esc(c.documento||'—')}</td><td>${esc(c.cidade||'—')}</td><td>${esc(c.origem||'—')} ${c.campanha?`<div class="muted">${esc(c.campanha)}</div>`:''}</td><td><button class="btn small" onclick="openClient('${c.id}')">Editar</button></td></tr>`).join('')}</tbody></table></div>`}
window.openClient=function(id){const c=state.clientes.find(x=>x.id===id)||{id:uid('cli'),nome:'',telefone:'',email:'',documento:'',cidade:'Várzea Grande',endereco:'',origem:'',campanha:'',anuncio:'',obs:''};modal(`<div class="modal-head"><strong>${id?'Editar':'Novo'} cliente</strong><button class="icon-btn" onclick="closeModal()">×</button></div><div class="modal-body"><div class="form-grid three">${fieldInput('Nome / Razão social','cNome','text',c.nome)}${fieldInput('Telefone / WhatsApp','cTel','text',c.telefone)}${fieldInput('E-mail','cEmail','email',c.email||'')}${fieldInput('CPF / CNPJ','cDoc','text',c.documento)}${fieldInput('Cidade','cCidade','text',c.cidade)}${fieldInput('Origem','cOrigem','text',c.origem||'')}${fieldInput('Campanha','cCampanha','text',c.campanha||'')}${fieldInput('Anúncio / conteúdo','cAnuncio','text',c.anuncio||'')}<div class="field full"><label>Endereço</label><input id="cEnd" value="${esc(c.endereco||'')}"></div><div class="field full"><label>Observações</label><textarea id="cObs">${esc(c.obs||'')}</textarea></div></div></div><div class="modal-foot"><button class="btn" onclick="closeModal()">Cancelar</button><button class="btn primary" onclick="saveClient('${c.id}',${Boolean(id)})">Salvar</button></div>`)}
window.saveClient=function(id,exists){const c={id,nome:$('#cNome').value.trim(),telefone:$('#cTel').value.trim(),email:$('#cEmail').value.trim(),documento:$('#cDoc').value.trim(),cidade:$('#cCidade').value.trim(),endereco:$('#cEnd').value.trim(),origem:$('#cOrigem').value.trim(),campanha:$('#cCampanha').value.trim(),anuncio:$('#cAnuncio').value.trim(),obs:$('#cObs').value.trim()};if(!c.nome)return toast('Informe o nome do cliente.');if(exists)state.clientes[state.clientes.findIndex(x=>x.id===id)]={...state.clientes.find(x=>x.id===id),...c};else state.clientes.push(c);audit(exists?'Cliente alterado':'Cliente cadastrado',c.nome,'clientes',id);save();closeModal();toast('Cliente salvo.')}

function renderProducts(){if(!canView('produtos'))return;const rows=state.produtos.slice().sort((a,b)=>(a.arquivado-b.arquivado)||(Number(a.ordem)||999)-(Number(b.ordem)||999)||a.nome.localeCompare(b.nome)),canEdit=['administrador','gerente'].includes(currentUser.role);$('#view-produtos').innerHTML=`<div class="row between" style="margin-bottom:12px"><div class="toolbar"><span class="pill ok">Publicados: ${state.produtos.filter(p=>!p.arquivado&&p.siteAtivo!==false).length}</span><span class="pill">Arquivados: ${state.produtos.filter(p=>p.arquivado).length}</span></div>${canEdit?'<button class="btn primary" onclick="openProduct()">+ Novo produto</button>':''}</div><div class="table-card">${productTable(rows,canEdit)}</div>`}
function productTable(rows,canEdit){if(!rows.length)return `<div class="empty"><strong>Nenhum produto cadastrado</strong>O responsável pela Universal fará os cadastros por aqui.</div>`;return `<div class="table-wrap"><table><thead><tr><th>Imagem</th><th>Produto</th><th>Categoria</th><th>Medida</th><th>Preço</th><th>Site</th><th>Status</th><th>Ações</th></tr></thead><tbody>${rows.map(p=>`<tr><td>${p.imagem?`<img class="thumb" src="${esc(p.imagem)}">`:'—'}</td><td><strong>${esc(p.nome)}</strong><div class="muted">${esc(p.codigo||'')}</div></td><td>${esc(p.categoria||'—')}</td><td>${esc(p.medidaPadrao||'—')}</td><td>${brl(p.preco)}</td><td><span class="pill ${p.siteAtivo!==false&&!p.arquivado?'ok':''}">${p.siteAtivo!==false&&!p.arquivado?'Publicado':'Oculto'}</span></td><td><span class="pill ${p.arquivado?'':'ok'}">${p.arquivado?'Arquivado':p.status==='indisponivel'?'Indisponível':'Ativo'}</span></td><td>${canEdit?`<div class="actions"><button class="btn small" onclick="openProduct('${p.id}')">Editar</button><button class="btn small ${p.arquivado?'success':'danger'}" onclick="toggleArchiveProduct('${p.id}')">${p.arquivado?'Reativar':'Arquivar'}</button></div>`:'Somente consulta'}</td></tr>`).join('')}</tbody></table></div>`}
window.openProduct=function(id){if(!['administrador','gerente'].includes(currentUser.role))return toast('Seu perfil não pode alterar produtos.');const p=state.produtos.find(x=>x.id===id)||{id:uid('prd'),nome:'',codigo:'',categoria:'Portão',medidaPadrao:state.empresa.medidaPortao,preco:0,prazoMedio:'',descricaoPublica:'',descricaoInterna:'',material:'',espessura:'',acabamento:'',cor:'',abertura:'',carga:3,status:'ativo',siteAtivo:true,destaque:false,ordem:999,imagem:'',galeria:[],arquivado:false};modal(`<div class="modal-head"><strong>${id?'Editar':'Novo'} produto</strong><button class="icon-btn" onclick="closeModal()">×</button></div><div class="modal-body"><div class="form-grid three">${fieldInput('Nome / modelo','prNome','text',p.nome)}${fieldInput('Código','prCodigo','text',p.codigo||'')}${fieldSelect('Categoria','prCat',p.categoria,[['Portão','Portão'],['Porta','Porta'],['Lixeira','Lixeira'],['Outro','Outro']])}${fieldInput('Medida padrão','prMed','text',p.medidaPadrao)}${fieldInput('Preço base','prPreco','number',p.preco,'min="0" step="0.01"')}${fieldInput('Prazo médio','prPrazo','text',p.prazoMedio||'')}${fieldInput('Material','prMaterial','text',p.material||'')}${fieldInput('Espessura','prEsp','text',p.espessura||'')}${fieldInput('Acabamento','prAcab','text',p.acabamento||'')}${fieldInput('Cor','prCor','text',p.cor||'')}${fieldInput('Abertura','prAbert','text',p.abertura||'')}${fieldInput('Carga estimada','prCarga','number',p.carga||1,'min="0" step="0.5"')}${fieldSelect('Disponibilidade','prStatus',p.status||'ativo',[['ativo','Ativo'],['indisponivel','Indisponível']])}${fieldSelect('Exibir no site','prSite',String(p.siteAtivo!==false),[['true','Sim'],['false','Não']])}${fieldSelect('Destaque','prDestaque',String(Boolean(p.destaque)),[['false','Não'],['true','Sim']])}${fieldInput('Ordem no catálogo','prOrdem','number',p.ordem||999,'min="1"')}</div><div style="height:14px"></div><div class="form-grid"><div class="field full"><label>Descrição pública</label><textarea id="prPub">${esc(p.descricaoPublica||'')}</textarea></div><div class="field full"><label>Descrição interna</label><textarea id="prInt">${esc(p.descricaoInterna||'')}</textarea></div></div><div class="divider"></div><div class="row between"><div><strong>Imagem principal</strong></div><label class="btn small">Selecionar imagem<input id="prImageFile" type="file" accept="image/*" hidden onchange="previewAndUploadProductImage(this)"></label></div><div style="height:10px"></div><div id="prImageBox" class="image-box">${p.imagem?`<img class="thumb big" src="${esc(p.imagem)}"><span class="muted">Imagem publicada no catálogo.</span>`:'<span class="muted">Nenhuma imagem principal.</span>'}</div><div class="divider"></div><div class="row between"><div><strong>Galeria complementar</strong></div><label class="btn small">+ Adicionar<input type="file" accept="image/*" hidden onchange="uploadProductGallery(this)"></label></div><div style="height:10px"></div><div id="prGallery" class="gallery"></div><div class="divider"></div><div class="notice">Portão padrão: ${esc(state.empresa.medidaPortao)}. Porta padrão: ${esc(state.empresa.medidaPorta)}. Estruturas metálicas são orçadas somente como serviço sob medida.</div></div><div class="modal-foot"><button class="btn" onclick="closeModal()">Cancelar</button><button class="btn primary" onclick="saveProduct('${p.id}',${Boolean(id)})">Salvar produto</button></div>`);window._productDraft=structuredClone(p);renderProductGallery()}
window.previewAndUploadProductImage=async function(input){const f=input.files?.[0];if(!f)return;try{const up=await uploadFile(f,'public');window._productDraft.imagem=up.url;$('#prImageBox').innerHTML=`<img class="thumb big" src="${esc(up.url)}"><span class="muted">${esc(f.name)}</span>`;toast('Imagem enviada. Salve o produto.')}catch(e){toast(e.message)}}
window.uploadProductGallery=async function(input){const f=input.files?.[0];if(!f)return;try{const up=await uploadFile(f,'public');window._productDraft.galeria=window._productDraft.galeria||[];window._productDraft.galeria.push(up);renderProductGallery();toast('Imagem adicionada.')}catch(e){toast(e.message)}}
function renderProductGallery(){const el=$('#prGallery');if(!el)return;el.innerHTML=(window._productDraft.galeria||[]).map((a,i)=>`<div class="gallery-item"><img class="thumb" src="${esc(a.url||a)}"><button onclick="removeGallery(${i})">×</button></div>`).join('')||'<span class="muted">Sem imagens complementares.</span>'}
window.removeGallery=function(i){window._productDraft.galeria.splice(i,1);renderProductGallery()}
window.saveProduct=function(id,exists){const p={...window._productDraft,id,nome:$('#prNome').value.trim(),codigo:$('#prCodigo').value.trim(),categoria:$('#prCat').value,medidaPadrao:$('#prMed').value.trim(),preco:Number($('#prPreco').value)||0,prazoMedio:$('#prPrazo').value.trim(),material:$('#prMaterial').value.trim(),espessura:$('#prEsp').value.trim(),acabamento:$('#prAcab').value.trim(),cor:$('#prCor').value.trim(),abertura:$('#prAbert').value.trim(),carga:Number($('#prCarga').value)||0,status:$('#prStatus').value,siteAtivo:$('#prSite').value==='true',destaque:$('#prDestaque').value==='true',ordem:Number($('#prOrdem').value)||999,descricaoPublica:$('#prPub').value.trim(),descricaoInterna:$('#prInt').value.trim()};if(!p.nome)return toast('Informe o nome do produto.');if(exists)state.produtos[state.produtos.findIndex(x=>x.id===id)]={...state.produtos.find(x=>x.id===id),...p};else state.produtos.push({...p,arquivado:false});audit(exists?'Produto alterado':'Produto cadastrado',p.nome,'produtos',id);save();closeModal();toast('Produto salvo. O catálogo será atualizado automaticamente.')}
window.toggleArchiveProduct=function(id){const p=state.produtos.find(x=>x.id===id);if(!p)return;p.arquivado=!p.arquivado;if(p.arquivado)p.siteAtivo=false;audit(p.arquivado?'Produto arquivado':'Produto reativado',p.nome,'produtos',p.id);save();toast(p.arquivado?'Produto arquivado. Histórico preservado.':'Produto reativado.')}
async function uploadFile(file,scope='private'){const fd=new FormData();fd.append('file',file);fd.append('scope',scope);return api('upload',{method:'POST',body:fd})}

function renderStock(){if(!canView('estoque'))return;state.estoqueMateriais=state.estoqueMateriais||[];state.movimentosEstoque=state.movimentosEstoque||[];const rows=state.estoqueMateriais.slice().sort((a,b)=>a.nome.localeCompare(b.nome)),canEdit=['administrador','gerente'].includes(currentUser.role),low=rows.filter(m=>Number(m.quantidade)<=Number(m.estoqueMinimo||0));$('#view-estoque').innerHTML=`<div class="grid cards"><div class="card"><div class="metric"><div class="label">Materiais cadastrados</div><div class="value">${rows.length}</div><div class="hint">itens de estoque</div></div></div><div class="card"><div class="metric"><div class="label">Estoque baixo</div><div class="value ${low.length?'danger-text':''}">${low.length}</div><div class="hint">no mínimo ou abaixo</div></div></div><div class="card"><div class="metric"><div class="label">Movimentos no mês</div><div class="value">${state.movimentosEstoque.filter(x=>(x.data||'').slice(0,7)===todayISO().slice(0,7)).length}</div><div class="hint">entradas, saídas e ajustes</div></div></div><div class="card"><div class="metric"><div class="label">Baixas por produção</div><div class="value">${state.movimentosEstoque.filter(x=>x.tipo==='saida_producao'&&(x.data||'').slice(0,7)===todayISO().slice(0,7)).length}</div><div class="hint">neste mês</div></div></div></div><div style="height:16px"></div><div class="table-card"><div class="table-tools"><div><strong>Materiais</strong><div class="muted">Saldo atual e estoque mínimo.</div></div>${canEdit?'<button class="btn primary" onclick="openMaterial()">+ Cadastrar material</button>':''}</div>${rows.length?`<div class="table-wrap"><table><thead><tr><th>Material</th><th>Unidade</th><th>Saldo</th><th>Mínimo</th><th>Situação</th><th>Ações</th></tr></thead><tbody>${rows.map(m=>{const q=Number(m.quantidade)||0,min=Number(m.estoqueMinimo)||0,crit=q<=min;return `<tr><td><strong>${esc(m.nome)}</strong><div class="muted">${esc(m.codigo||'')}</div></td><td>${esc(m.unidade||'—')}</td><td><strong class="${q<0?'danger-text':''}">${q.toLocaleString('pt-BR',{maximumFractionDigits:2})}</strong></td><td>${min.toLocaleString('pt-BR',{maximumFractionDigits:2})}</td><td><span class="pill ${crit?'danger':'ok'}">${crit?'Estoque baixo':'Normal'}</span></td><td>${canEdit?`<div class="actions"><button class="btn small" onclick="openStockEntry('${m.id}')">Entrada / ajuste</button><button class="btn small" onclick="openMaterial('${m.id}')">Editar</button></div>`:'Somente consulta'}</td></tr>`}).join('')}</tbody></table></div>`:'<div class="empty"><strong>Nenhum material cadastrado</strong>Cadastre tubos, chapas, barras, consumíveis e outros materiais.</div>'}</div><div style="height:16px"></div><div class="table-card"><div class="table-tools"><strong>Últimos movimentos</strong><span class="muted">Histórico preservado</span></div>${stockMovementTable(state.movimentosEstoque.slice(0,100))}</div>`}
function stockMovementTable(rows){if(!rows.length)return '<div class="empty compact">Nenhum movimento de estoque.</div>';return `<div class="table-wrap"><table><thead><tr><th>Data</th><th>Material</th><th>Tipo</th><th>Quantidade</th><th>OS</th><th>Responsável</th><th>Observação</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${dt(x.data)}</td><td>${esc(materialName(x.materialId))}</td><td>${x.tipo==='entrada'?'<span class="pill ok">Entrada</span>':x.tipo==='saida_producao'?'<span class="pill info">Produção</span>':'<span class="pill warn">Ajuste</span>'}</td><td class="${Number(x.efeito)<0?'danger-text':'ok-text'}">${Number(x.efeito)>0?'+':''}${Number(x.efeito||0).toLocaleString('pt-BR',{maximumFractionDigits:2})} ${esc(materialUnit(x.materialId))}</td><td>${esc(x.osNumero||'—')}</td><td>${esc(x.responsavel||'—')}</td><td>${esc(x.observacao||'—')}</td></tr>`).join('')}</tbody></table></div>`}
window.openMaterial=function(id){if(!['administrador','gerente'].includes(currentUser.role))return toast('Seu perfil não pode cadastrar materiais.');const m=state.estoqueMateriais.find(x=>x.id===id)||{id:uid('mat'),nome:'',codigo:'',unidade:'barra',quantidade:0,estoqueMinimo:0,ativo:true};modal(`<div class="modal-head"><strong>${id?'Editar':'Novo'} material</strong><button class="icon-btn" onclick="closeModal()">×</button></div><div class="modal-body"><div class="form-grid">${fieldInput('Material','matNome','text',m.nome)}${fieldInput('Código / referência','matCodigo','text',m.codigo||'')}${fieldInput('Unidade','matUnidade','text',m.unidade||'','placeholder="barra, m, kg, chapa, un, L..."')}${fieldInput('Estoque mínimo','matMin','number',m.estoqueMinimo||0,'min="0" step="0.01"')}${fieldSelect('Status','matAtivo',String(m.ativo!==false),[['true','Ativo'],['false','Inativo']])}${id?`<div class="field"><label>Saldo atual</label><input value="${Number(m.quantidade||0).toLocaleString('pt-BR')} ${esc(m.unidade||'')}" disabled><small class="muted">Use Entrada / ajuste para alterar o saldo.</small></div>`:fieldInput('Estoque inicial','matQtd','number',0,'step="0.01"')}</div></div><div class="modal-foot"><button class="btn" onclick="closeModal()">Cancelar</button><button class="btn primary" onclick="saveMaterial('${m.id}',${Boolean(id)})">Salvar</button></div>`)}
window.saveMaterial=function(id,exists){const old=state.estoqueMateriais.find(x=>x.id===id),initial=exists?Number(old?.quantidade||0):Number($('#matQtd').value)||0,m={id,nome:$('#matNome').value.trim(),codigo:$('#matCodigo').value.trim(),unidade:$('#matUnidade').value.trim(),quantidade:initial,estoqueMinimo:Number($('#matMin').value)||0,ativo:$('#matAtivo').value==='true'};if(!m.nome||!m.unidade)return toast('Informe material e unidade.');if(exists)state.estoqueMateriais[state.estoqueMateriais.findIndex(x=>x.id===id)]={...old,...m};else{state.estoqueMateriais.push(m);if(initial)state.movimentosEstoque.unshift({id:uid('mov'),materialId:id,tipo:'entrada',quantidade:Math.abs(initial),efeito:initial,data:todayISO(),responsavel:currentUser.name,observacao:'Estoque inicial',createdAt:new Date().toISOString()})}audit(exists?'Material de estoque alterado':'Material cadastrado',m.nome,'estoqueMateriais',id);save();closeModal();toast('Material salvo.')}
window.openStockEntry=function(id){if(!['administrador','gerente'].includes(currentUser.role))return toast('Seu perfil não pode lançar entradas ou ajustes.');const m=state.estoqueMateriais.find(x=>x.id===id);if(!m)return;modal(`<div class="modal-head"><strong>Movimentar estoque · ${esc(m.nome)}</strong><button class="icon-btn" onclick="closeModal()">×</button></div><div class="modal-body"><div class="notice">Saldo atual: <strong>${Number(m.quantidade||0).toLocaleString('pt-BR')} ${esc(m.unidade||'')}</strong></div><div style="height:14px"></div><div class="form-grid">${fieldSelect('Tipo','movTipo','entrada',[['entrada','Entrada de material'],['ajuste_mais','Ajuste positivo'],['ajuste_menos','Ajuste negativo']])}${fieldInput('Quantidade','movQtd','number',0,'min="0.01" step="0.01"')}<div class="field full"><label>Observação / referência</label><input id="movObs" placeholder="Ex.: compra NF 1234, correção de contagem..."></div></div></div><div class="modal-foot"><button class="btn" onclick="closeModal()">Cancelar</button><button class="btn primary" onclick="saveStockEntry('${id}')">Lançar</button></div>`)}
window.saveStockEntry=function(id){const m=state.estoqueMateriais.find(x=>x.id===id),tipo=$('#movTipo').value,q=Number($('#movQtd').value)||0;if(!m||q<=0)return toast('Informe uma quantidade válida.');const effect=tipo==='ajuste_menos'?-q:q;m.quantidade=(Number(m.quantidade)||0)+effect;state.movimentosEstoque.unshift({id:uid('mov'),materialId:id,tipo:tipo==='entrada'?'entrada':'ajuste',quantidade:q,efeito:effect,data:todayISO(),responsavel:currentUser.name,observacao:$('#movObs').value.trim(),createdAt:new Date().toISOString()});audit('Movimento de estoque',`${m.nome} · ${effect>0?'+':''}${effect} ${m.unidade}`,'estoqueMateriais',id);save();closeModal();toast('Estoque atualizado.')}

function renderSellers(){if(!canView('vendedores'))return;const rows=state.vendedores.slice().sort((a,b)=>a.nome.localeCompare(b.nome));$('#view-vendedores').innerHTML=`<div class="table-card"><div class="table-tools"><span class="muted">Responsáveis que podem constar nos orçamentos.</span><button class="btn primary" onclick="openSeller()">+ Novo vendedor</button></div>${rows.length?sellerTable(rows):'<div class="empty"><strong>Nenhum vendedor cadastrado</strong>Cadastre a equipe comercial.</div>'}</div>`}
function sellerTable(rows){return `<div class="table-wrap"><table><thead><tr><th>Nome</th><th>Telefone</th><th>Função</th><th>Status</th><th>Ações</th></tr></thead><tbody>${rows.map(v=>`<tr><td><strong>${esc(v.nome)}</strong></td><td>${esc(v.telefone||'—')}</td><td>${esc(v.funcao||'Vendedor')}</td><td><span class="pill ${v.ativo===false?'':'ok'}">${v.ativo===false?'Inativo':'Ativo'}</span></td><td><button class="btn small" onclick="openSeller('${v.id}')">Editar</button></td></tr>`).join('')}</tbody></table></div>`}
window.openSeller=function(id){const v=state.vendedores.find(x=>x.id===id)||{id:uid('ven'),nome:'',telefone:'',funcao:'Vendedor',ativo:true};modal(`<div class="modal-head"><strong>${id?'Editar':'Novo'} vendedor</strong><button class="icon-btn" onclick="closeModal()">×</button></div><div class="modal-body"><div class="form-grid">${fieldInput('Nome','vNome','text',v.nome)}${fieldInput('Telefone','vTel','text',v.telefone)}${fieldInput('Função','vFunc','text',v.funcao)}${fieldSelect('Status','vAtivo',String(v.ativo!==false),[['true','Ativo'],['false','Inativo']])}</div></div><div class="modal-foot"><button class="btn" onclick="closeModal()">Cancelar</button><button class="btn primary" onclick="saveSeller('${v.id}',${Boolean(id)})">Salvar</button></div>`)}
window.saveSeller=function(id,exists){const v={id,nome:$('#vNome').value.trim(),telefone:$('#vTel').value.trim(),funcao:$('#vFunc').value.trim(),ativo:$('#vAtivo').value==='true'};if(!v.nome)return toast('Informe o nome.');if(exists)state.vendedores[state.vendedores.findIndex(x=>x.id===id)]={...state.vendedores.find(x=>x.id===id),...v};else state.vendedores.push(v);audit(exists?'Vendedor alterado':'Vendedor cadastrado',v.nome,'vendedores',id);save();closeModal();toast('Vendedor salvo.')}

function renderProducers(){if(!canView('produtores'))return;const rows=state.produtores.slice().sort((a,b)=>a.nome.localeCompare(b.nome));$('#view-produtores').innerHTML=`<div class="table-card"><div class="table-tools"><span class="muted">Produtores não acessam o sistema; recebem a OS impressa.</span><button class="btn primary" onclick="openProducer()">+ Novo produtor</button></div>${rows.length?`<div class="table-wrap"><table><thead><tr><th>Nome</th><th>Especialidade</th><th>Telefone</th><th>Carga atual</th><th>Status</th><th>Ações</th></tr></thead><tbody>${rows.map(p=>{const load=state.pedidos.filter(o=>o.produtorId===p.id&&!['pronto','entregue','cancelado'].includes(o.status)).reduce((s,o)=>s+Number(o.carga||0),0);return `<tr><td><strong>${esc(p.nome)}</strong></td><td>${esc(p.especialidade||'—')}</td><td>${esc(p.telefone||'—')}</td><td>${load}</td><td><span class="pill ${p.ativo===false?'':'ok'}">${p.ativo===false?'Inativo':'Ativo'}</span></td><td><button class="btn small" onclick="openProducer('${p.id}')">Editar</button></td></tr>`}).join('')}</tbody></table></div>`:'<div class="empty"><strong>Nenhum produtor cadastrado</strong>Cadastre a equipe de fabricação.</div>'}</div>`}
window.openProducer=function(id){const p=state.produtores.find(x=>x.id===id)||{id:uid('pro'),nome:'',telefone:'',especialidade:'',ativo:true};modal(`<div class="modal-head"><strong>${id?'Editar':'Novo'} produtor</strong><button class="icon-btn" onclick="closeModal()">×</button></div><div class="modal-body"><div class="form-grid">${fieldInput('Nome','proNome','text',p.nome)}${fieldInput('Telefone','proTel','text',p.telefone)}${fieldInput('Especialidade','proEsp','text',p.especialidade||'')}${fieldSelect('Status','proAtivo',String(p.ativo!==false),[['true','Ativo'],['false','Inativo']])}</div></div><div class="modal-foot"><button class="btn" onclick="closeModal()">Cancelar</button><button class="btn primary" onclick="saveProducer('${p.id}',${Boolean(id)})">Salvar</button></div>`)}
window.saveProducer=function(id,exists){const p={id,nome:$('#proNome').value.trim(),telefone:$('#proTel').value.trim(),especialidade:$('#proEsp').value.trim(),ativo:$('#proAtivo').value==='true'};if(!p.nome)return toast('Informe o nome.');if(exists)state.produtores[state.produtores.findIndex(x=>x.id===id)]={...state.produtores.find(x=>x.id===id),...p};else state.produtores.push(p);audit(exists?'Produtor alterado':'Produtor cadastrado',p.nome,'produtores',id);save();closeModal();toast('Produtor salvo.')}

function renderReports(){if(!canView('relatorios'))return;const approved=state.orcamentos.filter(o=>o.status==='aprovado'),conversion=state.orcamentos.length?Math.round(approved.length/state.orcamentos.length*100):0,delivered=state.pedidos.filter(p=>p.status==='entregue'),late=state.pedidos.filter(p=>!['entregue','cancelado'].includes(p.status)&&p.prazoEntrega&&p.prazoEntrega<todayISO());$('#view-relatorios').innerHTML=`<div class="grid report-grid">${metric('Conversão de orçamentos',conversion+'%','aprovados / total')}${metric('Valor aprovado',brl(approved.reduce((s,o)=>s+calcBudget(o).final,0)),'histórico')}${metric('Pedidos entregues',delivered.length,'concluídos')}${metric('Pedidos atrasados',late.length,'abertos com prazo vencido',late.length?'danger-text':'')}${metric('Produtos publicados',state.produtos.filter(p=>!p.arquivado&&p.siteAtivo!==false).length,'no site público')}${metric('Produtores ativos',state.produtores.filter(p=>p.ativo!==false).length,'equipe de fabricação')}</div><div style="height:16px"></div><div class="grid kpi-split"><div class="card"><h3 class="section-title">Produção por responsável</h3><div style="height:12px"></div>${producerReport()}</div><div class="card"><h3 class="section-title">Marketing · últimos 30 dias</h3><div id="marketingBox" style="margin-top:12px"><span class="muted">Carregando eventos do site...</span></div></div></div>`}
function producerReport(){const rows=state.produtores.map(p=>({name:p.nome,active:state.pedidos.filter(o=>o.produtorId===p.id&&!['pronto','entregue','cancelado'].includes(o.status)).length,done:state.pedidos.filter(o=>o.produtorId===p.id&&['pronto','entregue'].includes(o.status)).length,load:state.pedidos.filter(o=>o.produtorId===p.id&&!['pronto','entregue','cancelado'].includes(o.status)).reduce((s,o)=>s+Number(o.carga||0),0)}));return rows.length?`<div class="list">${rows.map(r=>`<div class="list-item"><div><strong>${esc(r.name)}</strong><div class="muted">${r.active} ativa(s) · ${r.done} concluída(s)</div></div><span class="pill">Carga ${r.load}</span></div>`).join('')}</div>`:'<div class="empty">Sem produtores cadastrados.</div>'}
async function loadMarketing(){if(currentView!=='relatorios'||!canView('relatorios'))return;try{const r=await api('marketing?days=30'),rows=r.rows||[],clicks=rows.filter(x=>x.event_type==='whatsapp_click').reduce((s,x)=>s+Number(x.total),0),views=rows.filter(x=>x.event_type==='page_view').reduce((s,x)=>s+Number(x.total),0),top=rows.filter(x=>x.campaign).sort((a,b)=>b.total-a.total).slice(0,5);const box=$('#marketingBox');if(box)box.innerHTML=`<div class="list"><div class="list-item"><span>Visualizações registradas</span><strong>${views}</strong></div><div class="list-item"><span>Cliques no WhatsApp</span><strong>${clicks}</strong></div>${top.map(x=>`<div class="list-item"><div><strong>${esc(x.campaign)}</strong><div class="muted">${esc(x.source||'direto')} · ${esc(x.event_type)}</div></div><span class="pill">${x.total}</span></div>`).join('')}</div>`}catch(e){const box=$('#marketingBox');if(box)box.innerHTML=`<span class="muted">${esc(e.message)}</span>`}}

async function loadUsers(){if(currentUser.role!=='administrador')return;try{const r=await api('users');usersCache=r.users||[];renderUsers()}catch(e){toast(e.message)}}

function renderUsers(){if(currentUser.role!=='administrador')return;$('#view-usuarios').innerHTML=`<div class="table-card"><div class="table-tools"><span class="muted">Cada pessoa deve usar seu próprio login.</span><button class="btn primary" onclick="openUser()">+ Novo usuário</button></div>${usersCache.length?`<div class="table-wrap"><table><thead><tr><th>Nome</th><th>E-mail</th><th>Perfil</th><th>Permissões</th><th>Status</th><th>Ações</th></tr></thead><tbody>${usersCache.map(u=>`<tr><td><strong>${esc(u.name)}</strong></td><td>${esc(u.email)}</td><td>${roleLabel(u.role)}</td><td><span class="permission-note">Desconto: ${u.permissions?.discount?'sim':'não'} · Transferência: ${u.permissions?.transferProduction?'sim':'não'}</span></td><td><span class="pill ${u.active?'ok':'danger'}">${u.active?'Ativo':'Inativo'}</span>${u.mustChangePassword?'<div class="muted">senha temporária</div>':''}</td><td><div class="actions"><button class="btn small" onclick="openUser('${u.id}')">Editar</button><button class="btn small" onclick="resetUserPassword('${u.id}')">Redefinir senha</button></div></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Nenhum usuário.</div>'}</div>`}
window.openUser=function(id){const u=usersCache.find(x=>x.id===id)||{name:'',email:'',role:'vendedor',permissions:{discount:false,transferProduction:false},active:true};modal(`<div class="modal-head"><strong>${id?'Editar':'Novo'} usuário</strong><button class="icon-btn" onclick="closeModal()">×</button></div><div class="modal-body"><div class="form-grid">${fieldInput('Nome','uName','text',u.name)}${id?`<div class="field"><label>E-mail</label><input value="${esc(u.email)}" disabled></div>`:fieldInput('E-mail','uEmail','email',u.email)}${fieldSelect('Perfil','uRole',u.role,[['administrador','Administrador'],['gerente','Gerente'],['vendedor','Vendedor'],['conferencia','Conferência'],['entrega','Entrega']])}${fieldSelect('Status','uActive',String(u.active!==false),[['true','Ativo'],['false','Inativo']])}${id?'':fieldInput('Senha temporária','uPassword','password','','minlength="8"')}<div class="field"><label>Permitir desconto</label><select id="uDiscount"><option value="false" ${!u.permissions?.discount?'selected':''}>Não</option><option value="true" ${u.permissions?.discount?'selected':''}>Sim</option></select></div><div class="field"><label>Transferir responsável da produção</label><select id="uTransfer"><option value="false" ${!u.permissions?.transferProduction?'selected':''}>Não</option><option value="true" ${u.permissions?.transferProduction?'selected':''}>Sim</option></select></div></div>${!id?'<div class="notice warn" style="margin-top:14px">O usuário será obrigado a trocar a senha temporária no primeiro acesso.</div>':''}</div><div class="modal-foot"><button class="btn" onclick="closeModal()">Cancelar</button><button class="btn primary" onclick="saveUser('${id||''}')">Salvar usuário</button></div>`)}
window.saveUser=async function(id){const body={name:$('#uName').value.trim(),role:$('#uRole').value,active:$('#uActive').value==='true',permissions:{discount:$('#uDiscount').value==='true',transferProduction:$('#uTransfer').value==='true'}};if(!id){body.email=$('#uEmail').value.trim();body.password=$('#uPassword').value}try{await api(id?'users/'+encodeURIComponent(id):'users',{method:id?'PUT':'POST',body:JSON.stringify(body)});closeModal();await loadUsers();toast('Usuário salvo.')}catch(e){toast(e.message)}}
window.resetUserPassword=function(id){modal(`<div class="modal-head"><strong>Redefinir senha</strong><button class="icon-btn" onclick="closeModal()">×</button></div><div class="modal-body">${fieldInput('Nova senha temporária','resetPassword','password','','minlength="8"')}<div class="notice warn" style="margin-top:12px">As sessões atuais serão encerradas e a troca será obrigatória no próximo acesso.</div></div><div class="modal-foot"><button class="btn" onclick="closeModal()">Cancelar</button><button class="btn primary" onclick="doResetPassword('${id}')">Redefinir</button></div>`)}
window.doResetPassword=async function(id){try{await api(`users/${encodeURIComponent(id)}/reset-password`,{method:'POST',body:JSON.stringify({password:$('#resetPassword').value})});closeModal();await loadUsers();toast('Senha temporária redefinida.')}catch(e){toast(e.message)}}

function renderAudit(){if(!canView('auditoria'))return;const rows=(state.auditoria||[]).slice(0,300);$('#view-auditoria').innerHTML=`<div class="table-card">${rows.length?`<div class="table-wrap"><table><thead><tr><th>Data / hora</th><th>Usuário</th><th>Ação</th><th>Detalhe</th><th>Registro</th></tr></thead><tbody>${rows.map(a=>`<tr><td>${new Date(a.at).toLocaleString('pt-BR',{timeZone:'America/Cuiaba'})}</td><td><strong>${esc(a.userName||'Sistema')}</strong><div class="muted">${esc(roleLabel(a.role||''))}</div></td><td>${esc(a.action)}</td><td>${esc(a.detail||'')}</td><td>${a.before||a.after?`<button class="btn small" onclick="viewAudit('${a.id}')">Antes / depois</button>`:'—'}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty"><strong>Sem registros ainda</strong>Alterações críticas aparecerão aqui.</div>'}</div>`}
window.viewAudit=function(id){const a=state.auditoria.find(x=>x.id===id);if(!a)return;modal(`<div class="modal-head"><strong>${esc(a.action)}</strong><button class="icon-btn" onclick="closeModal()">×</button></div><div class="modal-body"><div class="form-grid"><div><strong>Antes</strong><pre style="white-space:pre-wrap;font-size:11px;background:#f7f7f7;padding:12px;border-radius:8px">${esc(JSON.stringify(a.before,null,2)||'—')}</pre></div><div><strong>Depois</strong><pre style="white-space:pre-wrap;font-size:11px;background:#f7f7f7;padding:12px;border-radius:8px">${esc(JSON.stringify(a.after,null,2)||'—')}</pre></div></div></div><div class="modal-foot"><button class="btn" onclick="closeModal()">Fechar</button></div>`)}

function renderConfig(){if(!canView('config'))return;const e=state.empresa;$('#view-config').innerHTML=`<div class="grid config-grid"><div class="card"><h3 class="section-title">Dados da empresa</h3><div style="height:14px"></div><div class="form-grid"><div class="field full"><label>Nome fantasia</label><input id="cfgNome" value="${esc(e.nome)}"></div><div class="field full"><label>Razão social</label><input id="cfgRazao" value="${esc(e.razaoSocial||'')}"></div>${fieldInput('CNPJ','cfgCnpj','text',e.cnpj||'')}${fieldInput('Telefone','cfgTel','text',e.telefone)}${fieldInput('WhatsApp (somente números)','cfgWhats','text',e.whatsapp||'')}${fieldInput('URL da logo para documentos','cfgLogo','text',e.logoUrl||'')}<div class="field full"><label>Endereço</label><input id="cfgEnd" value="${esc(e.endereco)}"></div>${fieldInput('Validade padrão (dias)','cfgVal','number',e.validade||7,'min="1"')}</div></div><div class="card"><h3 class="section-title">Regras comerciais</h3><div style="height:14px"></div><div class="form-grid">${fieldInput('Medida padrão do portão','cfgPortao','text',e.medidaPortao||'3,10 x 2,10 m')}${fieldInput('Medida padrão da porta','cfgPorta','text',e.medidaPorta||'0,80 x 2,10 m')}${fieldInput('Frete Várzea Grande','cfgVG','number',Number(e.freteVG)||0)}${fieldInput('Frete Cuiabá','cfgCba','number',Number(e.freteCuiaba)||100)}</div><div style="height:14px"></div><div class="notice">Regra atual: Várzea Grande grátis; Cuiabá R$ 100. Instalação e automatização não fazem parte da venda pelo site.</div></div><div class="card"><h3 class="section-title">Rastreamento</h3><div style="height:14px"></div><div class="form-grid">${fieldInput('Google Analytics 4 ID','cfgGA','text',e.ga4Id||'')}${fieldInput('Meta Pixel ID','cfgMeta','text',e.metaPixelId||'')}</div><div style="height:14px"></div><div class="notice">O site também registra UTM, campanha, produto e clique no WhatsApp no banco. A venda deve ser vinculada ao cliente/pedido para concluir a atribuição comercial.</div></div><div class="card"><h3 class="section-title">Infraestrutura</h3><div style="height:14px"></div><div class="list"><div class="list-item"><span>Banco de dados</span><strong>Cloudflare D1</strong></div><div class="list-item"><span>Arquivos</span><strong>Cloudflare R2 privado</strong></div><div class="list-item"><span>Publicação</span><strong>GitHub + Cloudflare Pages</strong></div><div class="list-item"><span>PWA</span><strong>Instalável</strong></div></div></div></div><div style="height:16px"></div><div class="row between"><div class="notice" style="flex:1">Produtos cadastrados e publicados aqui atualizam o catálogo do site sem editar o código.</div><button class="btn primary" onclick="saveConfig()">Salvar configurações</button></div>`}
window.saveConfig=function(){state.empresa={...state.empresa,nome:$('#cfgNome').value.trim(),razaoSocial:$('#cfgRazao').value.trim(),cnpj:$('#cfgCnpj').value.trim(),telefone:$('#cfgTel').value.trim(),whatsapp:$('#cfgWhats').value.trim(),logoUrl:$('#cfgLogo').value.trim(),endereco:$('#cfgEnd').value.trim(),validade:Number($('#cfgVal').value)||15,medidaPortao:$('#cfgPortao').value.trim(),medidaPorta:$('#cfgPorta').value.trim(),freteVG:Number($('#cfgVG').value)||0,freteCuiaba:Number($('#cfgCba').value)||100,ga4Id:$('#cfgGA').value.trim(),metaPixelId:$('#cfgMeta').value.trim()};audit('Configurações alteradas','Dados da empresa, regras comerciais ou rastreamento','empresa','');save();toast('Configurações salvas.')}

$('#quickBudgetBtn').onclick=()=>openBudget();$('#backupBtn').onclick=()=>{const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`universal-backup-${todayISO()}.json`;a.click();URL.revokeObjectURL(a.href);toast('Backup exportado.')};$('#restoreInput').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{const data=JSON.parse(await f.text());if(!data||!Array.isArray(data.orcamentos)||!Array.isArray(data.pedidos))throw new Error();state={...structuredClone(defaultState),...data,empresa:{...defaultState.empresa,...(data.empresa||{})}};audit('Backup importado',f.name);await save();toast('Backup importado.')}catch{toast('Arquivo de backup inválido.')}e.target.value=''};

window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;$('#installBtn').style.display='inline-flex'});$('#installBtn').onclick=async()=>{if(!installPrompt)return;installPrompt.prompt();await installPrompt.userChoice;installPrompt=null;$('#installBtn').style.display='none'};if('serviceWorker'in navigator)navigator.serviceWorker.register('/painel/sw.js',{scope:'/painel/'}).catch(()=>{});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('#modal').open)closeModal()});
window.switchView=switchView;window.closeModal=closeModal;
